# Define level mapping and required usage string
LEVELS = {"INFO": 1, "WARN": 2, "ERROR": 3}
USAGE_MSG = "Usage: python logscan.py PATH LEVEL [--at-least] [--limit N]"

def print_usage_error(message=""):
    """Prints usage error message and exits status 2."""
    if message:
        sys.stderr.write(f"{message}\n")
    sys.stderr.write(USAGE_MSG + "\n")
    sys.exit(2)

def parse_arguments(args):
    """Parses command-line arguments, robustly handling mixed order."""

    path = None
    target_level_str = None
    at_least = False
    limit = None

    # Use a standard approach to find known flags first, then identify positional arguments
    i = 0
    while i < len(args):
        arg = args[i]

        if arg == '--at-least':
            at_least = True
            i += 1
            continue
        elif arg == '--limit':
            if i + 1 >= len(args):
                print_usage_error("Error: --limit requires an integer argument.")
            try:
                limit_val = args[i+1]
                limit = int(limit_val)
                if limit < 0:
                    print_usage_error("Error: --limit must be a non-negative integer.")
            except ValueError:
                print_usage_error("Error: --limit argument must be an integer.")
            i += 2
            continue
        elif arg.startswith('--'):
            # Unknown flag
            print_usage_error(f"Error: Unknown option '{arg}'.")
        else:
            # Positional argument. We need to determine if it's PATH or LEVEL.
            # Since we don't know the order, we must collect all non-flag args 
            # and rely on the count (should be 2) and the fact that LEVEL is constrained.

            if path is None and target_level_str is None:
                # Tentatively assign to path, unless it looks like a level
                if arg.upper() in LEVELS:
                    target_level_str = arg
                else:
                    path = arg
            elif target_level_str is None:
                # If path is set, this must be the level
                target_level_str = arg
            else:
                # Too many positional arguments
                print_usage_error("Error: Too many positional arguments provided.")

            i += 1

    # Final check for required positional arguments
    if path is None or target_level_str is None:
        print_usage_error("Error: Missing PATH or LEVEL argument.")

    # Validate target level *before* returning
    if target_level_str.upper() not in LEVELS:
        print_usage_error(f"Error: Invalid target log level '{target_level_str}'.")

    return path, target_level_str, at_least, limit

def get_log_level_value(level_str):
    """Returns the numeric weight for a given level string."""
    # We rely on the caller (parse_arguments) to ensure this string is valid
    return LEVELS.get(level_str.upper())

def logscan():
    """Main function to run logscan."""

    if len(sys.argv) < 2:
        print_usage_error("Missing required arguments.")

    try:
        # Pass arguments starting from the first one (index 1)
        path, target_level_str, at_least, limit = parse_arguments(sys.argv[1:])
    except SystemExit as e:
        # Catch exits from argument parsing functions (which handle printing usage)
        sys.exit(e.code)

    # 1. Validate PATH existence
    if not os.path.exists(path) or not os.path.isfile(path):
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

    # 2. Determine target level weight (This should already be validated by parse_arguments, 
    # but we re-fetch it for safety/clarity)
    target_level_weight = get_log_level_value(target_level_str)

    # 3. Process file
    matching_lines_output = []
    total_matches = 0

    try:
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:

                # Preserve original line content, including potential newline
                original_line = line

                # We need to process the line content to extract level
                stripped_line = line.rstrip('\r\n')
                parts = stripped_line.split()

                # Check minimum field requirement
                if len(parts) < 3:
                    continue

                # The level is the third field (index 2)
                log_level_str = parts[2]

                level_weight = None
                if log_level_str.upper() in LEVELS:
                    level_weight = get_log_level_value(log_level_str)

                if level_weight is None:
                    continue

                # Check matching criteria
                is_match = False
                if at_least:
                    # Match if line level >= target level
                    if level_weight >= target_level_weight:
                        is_match = True
                else:
                    # Match only if line level == target level
                    if level_weight == target_level_weight:
                        is_match = True

                if is_match:
                    total_matches += 1

                    # Print to stdout if within limit
                    if limit is None or total_matches <= limit:
                        # Crucial change: If the original line lacked a newline, add one 
                        # to satisfy the requirement "followed by a newline (also for a last line that had no trailing newline in the file)."
                        if not original_line.endswith('\n'):
                            matching_lines_output.append(original_line + '\n')
                        else:
                            matching_lines_output.append(original_line)

                    # Stop if limit reached (and limit is set)
                    if limit is not None and total_matches >= limit:
                        break

    except IOError:
        # Should only catch unexpected read errors after existence check
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

    # 4. Output results

    # Print matching lines to stdout
    sys.stdout.writelines(matching_lines_output)

    # Print count to stderr
    sys.stderr.write(f"count={total_matches}\n")

if __name__ == "__main__":
    logscan()
