    def __init__(self, parsed_data: Dict[str, Dict[str, str]]):
        # Internal storage: {section_name: {key: value}} (values are guaranteed strings here)
        self._data: Dict[str, Dict[str, str]] = parsed_data
        # Ordered list of sections as they appeared
        self._section_order: List[str] = list(parsed_data.keys())

    def sections(self) -> List[str]:
        """Returns the section names in the order they appear."""
        return self._section_order

    def keys(self, section: str) -> List[str]:
        """Returns the keys of a section in the order they appeared."""
        if section not in self._data:
            raise KeyError(f"Section '{section}' not found.")
        # Order is preserved by insertion order in standard Python dicts (3.7+)
        return list(self._data[section].keys())

    def get(self, section: str, key: str, default: Any = None) -> Union[str, None]:
        """Retrieves the value as a string, or default if not found."""
        if section not in self._data:
            return default
        if key not in self._data[section]:
            return default
        return self._data[section][key]

    def getint(self, section: str, key: str, default: Any = None) -> Union[int, None]:
        """Retrieves the value as an integer."""
        value_str = self.get(section, key, default=None)

        if value_str is None:
            return default

        # Ensure value_str is treated as a string for validation if default was None
        if not isinstance(value_str, str):
            # Should not happen if parsing is correct, but defensive check
            return default 

        try:
            # Strict integer conversion: allows optional sign, followed by digits.
            # Python's int() handles '+' and '-' correctly for valid integers.
            # It fails for '4.0', '0x10', or ''.
            return int(value_str)
        except ValueError:
            # Conversion failed (e.g., '4.0', '', 'abc')
            if default is not None:
                return default
            # If default was None, raise error as required by spec for invalid value
            raise ValueError(f"Value '{value_str}' is not a valid integer.")

    def getbool(self, section: str, key: str, default: Any = None) -> Union[bool, None]:
        """Retrieves the value as a boolean."""
        value_str = self.get(section, key, default=None)
        if value_str is None:
            return default

        lower_val = value_str.lower()
        if lower_val in ('true', 'yes', 'on', '1'):
            return True
        if lower_val in ('false', 'no', 'off', '0'):
            return False

        # If it's not recognized, raise ValueError if no default was provided
        if default is None:
            raise ValueError(f"Value '{value_str}' is not a valid boolean.")

        return default


    def getlist(self, section: str, key: str, default: Any = None) -> Union[List[str], None]:
        """Retrieves the value as a comma-separated list."""
        value_str = self.get(section, key, default=None)
        if value_str is None:
            return default

        # Split on comma, strip whitespace, filter out empty strings
        return [item.strip() for item in value_str.split(',') if item.strip()]


def parse(text: str) -> Config:
    """
    Parses the INI-style configuration text.

    Raises:
        ParseError: If any syntax or structural error is found.
    """
    lines = text.splitlines()

    current_section: str | None = None

    # Stores processed data: {section_name: {key: [value_part_1, value_part_2, ...]}}
    raw_data: Dict[str, Dict[str, List[str]]] = {}

    # Track keys seen per section to detect duplicates
    section_keys_seen: Dict[str, set[str]] = {}

    # Track the key associated with the last assignment for continuation lines
    last_assigned_key: str | None = None

    for lineno, line_full in enumerate(lines, 1):
        line = line_full.rstrip()

        # 1. Handle Blank Lines & Comments
        stripped_line = line.lstrip()
        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            # Reset key tracker if we hit a blank line/comment, as continuation must follow directly
            last_assigned_key = None
            continue

        # Check for indentation
        indentation = len(line) - len(stripped_line)

        # --- Section Header ---
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            # Must not be indented
            if indentation > 0:
                raise ParseError("Section header must not be indented.", lineno)

            name_raw = stripped_line[1:-1].strip()

            if not name_raw:
                raise ParseError("Section name cannot be empty.", lineno)

            if name_raw in raw_data:
                raise ParseError(f"Section '{name_raw}' already defined.", lineno)

            current_section = name_raw
            raw_data[current_section] = {}
            section_keys_seen[current_section] = set()
            last_assigned_key = None # Reset key tracking on section change
            continue

        # --- Key/Value or Continuation Line ---

        # Must be inside a section
        if current_section is None:
            raise ParseError("Key/value line found before any section header.", lineno)

        # 2. Key Line (Not indented)
        if indentation == 0:
            if '=' not in stripped_line:
                # If it wasn't a header, it must be a key=value line, or an error.
                raise ParseError("Line does not conform to expected INI syntax (must be header or key=value).", lineno)

            key_raw, value_raw = stripped_line.split('=', 1)
            key = key_raw.strip()
            value = value_raw.strip()

            if not key:
                raise ParseError("Key cannot be empty.", lineno)

            if key in section_keys_seen[current_section]:
                raise ParseError(f"Key '{key}' already defined in section [{current_section}].", lineno)

            # Initialize the key with its first part
            raw_data[current_section][key] = [value]
            section_keys_seen[current_section].add(key)

            # Update state tracker
            last_assigned_key = key
            continue

        # 3. Continuation Line (Indented)
        if indentation > 0:
            if last_assigned_key is None:
                # Indented line found, but no key assignment preceded it (or previous line was ignored)
                raise ParseError("Indented line found without preceding key assignment.", lineno)

            # Continuation line must not be blank or a comment (checked at the start)
            # Append to the value using '\n'
            current_value_parts = raw_data[current_section][last_assigned_key]
            current_value_parts.append(line.strip())
            # State tracker remains the same: we are continuing the same key
            continue

        # 4. Catch-all for unhandled lines (should only be reached if indentation was 0 but no '=' was found, which is already caught)
        raise ParseError("Line does not conform to expected INI syntax.", lineno)


    # --- Final Conversion to String Values ---

    final_data: Dict[str, Dict[str, str]] = {}
    for section, keys_map in raw_data.items():
        final_data[section] = {}
        for key, parts in keys_map.items():
            # Join continuation parts with '\n'
            final_data[section][key] = "\n".join(parts)

    return Config(final_data)
