PRE_RELEASE_PATTERN = f"({IDENTIFIER_PATTERN}(\\.{IDENTIFIER_PATTERN})*)"
# Build metadata identifier list: dot-separated identifiers
BUILD_PATTERN = f"({IDENTIFIER_PATTERN}(\\.{IDENTIFIER_PATTERN})*)"

# Full SemVer regex: MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
SEMVER_REGEX = re.compile(
    r"^(?P<major>0|[1-9]\d*)\."
    r"(?P<minor>0|[1-9]\d*)\."
    r"(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>" + PRE_RELEASE_PATTERN + r"))?"
    r"(?:\+(?P<build>" + BUILD_PATTERN + r"))?$"
)

# --- Helper Functions for Identifier Parsing ---

def _parse_identifier(identifier_str: str) -> Union[int, str]:
    """
    Parses an identifier string. If it's numeric, returns int, else str.
    Raises ValueError for invalid numeric identifiers (leading zero).
    """
    if not identifier_str:
        # This should be caught by split logic, but defensively checking here.
        raise ValueError("Identifier cannot be empty.")

    if identifier_str.isdigit():
        if len(identifier_str) > 1 and identifier_str.startswith('0'):
            raise ValueError(f"Numeric identifier '{identifier_str}' must not have leading zeros.")
        return int(identifier_str)
    else:
        # Alphanumeric identifier
        return identifier_str

# --- Version Class Implementation ---

class Version:
    """
    Represents a Semantic Version 2.0.0 number.
    """
    def __init__(self, major: int, minor: int, patch: int, 
                 prerelease: Tuple[Union[int, str], ...] = (), 
                 build: Tuple[str, ...] = ()):
        self.major = major
        self.minor = minor
        self.patch = patch
        # Prerelease and build identifiers are stored as tuples of parsed elements
        self.prerelease = prerelease
        self.build = build

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """
        Parses a full SemVer string into a Version object.
        """
        text = text.strip()

        match = SEMVER_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid SemVer format or structure: '{text}'")

        groups = match.groupdict()

        # 1. Parse core version numbers
        try:
            major = int(groups['major'])
            minor = int(groups['minor'])
            patch = int(groups['patch'])
        except ValueError:
            raise ValueError(f"Core version parts are not valid integers in: '{text}'")

        prerelease = tuple()
        build = tuple()

        # 2. Parse prerelease identifiers
        if groups['prerelease']:
            prerelease_str = groups['prerelease']
            identifiers = prerelease_str.split('.')
            parsed_prerelease = []
            for identifier in identifiers:
                if not identifier:
                    raise ValueError(f"Empty identifier in prerelease: '{text}'")
                try:
                    parsed_prerelease.append(_parse_identifier(identifier))
                except ValueError as e:
                    raise ValueError(f"Invalid prerelease identifier in '{text}': {e}")
            prerelease = tuple(parsed_prerelease)

        # 3. Parse build identifiers
        if groups['build']:
            build_str = groups['build']
            identifiers = build_str.split('.')
            parsed_build = []
            for identifier in identifiers:
                if not identifier:
                    raise ValueError(f"Empty identifier in build metadata: '{text}'")
                # Build identifiers are always strings, as per standard practice/spec interpretation here
                parsed_build.append(identifier) 
            build = tuple(parsed_build)

        return cls(major, minor, patch, prerelease, build)

    def __str__(self) -> str:
        """Returns the canonical text used for parsing."""
        parts = []
        parts.append(f"{self.major}.{self.minor}.{self.patch}")

        if self.prerelease:
            parts.append("-" + ".".join(map(str, self.prerelease)))

        if self.build:
            parts.append("+" + ".".join(self.build))

        return "".join(parts)

    # --- Comparison Logic ---

    def _compare_identifiers(self, a: Union[int, str], b: Union[int, str]) -> int:
        """Compares two single pre-release identifiers."""
        if isinstance(a, int) and isinstance(b, int):
            return a - b
        if isinstance(a, int):
            # Numeric is lower than alphanumeric
            return -1
        if isinstance(b, int):
            # Alphanumeric is higher than numeric
            return 1

        # Both are strings (alphanumeric comparison)
        if a < b:
            return -1
        if a > b:
            return 1
        return 0

    def _compare_prerelease(self, pr1: Tuple, pr2: Tuple) -> int:
        """Compares two pre-release tuples."""
        len1 = len(pr1)
        len2 = len(pr2)
        max_len = max(len1, len2)

        for i in range(max_len):
            id1 = pr1[i] if i < len1 else None
            id2 = pr2[i] if i < len2 else None

            if id1 is None and id2 is None:
                break
            if id1 is None:
                # Shorter list is lower if all prior identifiers were equal
                return -1
            if id2 is None:
                return 1

            comparison = self._compare_identifiers(id1, id2)
            if comparison != 0:
                return comparison
        return 0 # They are equal

    def _compare_versions_precedence(self, other: 'Version') -> int:
        """
        Compares two versions based on SemVer precedence, ignoring build metadata.
        Returns: -1 if self < other, 0 if self == other, 1 if self > other.
        """
        # 1. Compare core version numbers (MAJOR.MINOR.PATCH)
        if self.major != other.major:
            return self.major - other.major
        if self.minor != other.minor:
            return self.minor - other.minor
        if self.patch != other.patch:
            return self.patch - other.patch

        # Core versions are equal. Now compare pre-release status.
        has_pr1 = bool(self.prerelease)
        has_pr2 = bool(other.prerelease)

        if has_pr1 and not has_pr2:
            # A pre-release is lower than the final release of the same core
            return -1
        if not has_pr1 and has_pr2:
            return 1

        if has_pr1 and has_pr2:
            # Both have pre-release tags, compare identifiers
            pr_cmp = self._compare_prerelease(self.prerelease, other.prerelease)
            if pr_cmp != 0:
                return pr_cmp

        # If core versions and prerelease tags are equivalent (or both absent), they are equal
        return 0

    # --- Magic Methods for Comparison ---

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Build metadata is ignored for equality checks
        return self._compare_versions_precedence(other) == 0

    def __hash__(self) -> int:
        # Hash must agree with equality check (ignoring build metadata)
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __lt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_versions_precedence(other) < 0

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_versions_precedence(other) <= 0

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_versions_precedence(other) > 0

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare_versions_precedence(other) >= 0

    def __ne__(self, other) -> bool:
        return not self.__eq__(other)

    # --- Bump Functionality ---

    def bump(self, kind: str) -> 'Version':
        """
        Increments the version based on the kind ('major', 'minor', 'patch').
        Resets prerelease/build tags.
        """
        kind = kind.lower()
        if kind == 'major':
            return Version(self.major + 1, 0, 0)
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0)
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: '{kind}'. Must be 'major', 'minor', or 'patch'.")

# --- Range Satisfaction Implementation ---

def _parse_partial_version(text: str) -> Version:
    """
    Parses a partial version (e.g., '1', '1.2') assuming patch is 0.
    Raises ValueError if pre-release or build is present, or if components are invalid.
    """
    text = text.strip()
    parts = text.split('.')

    if len(parts) > 3:
        raise ValueError(f"Partial version '{text}' has too many components.")

    # Crucial check: Partial versions cannot have pre-release or build
    if '-' in text or '+' in text:
        raise ValueError(f"Partial version '{text}' cannot contain pre-release or build metadata.")

    try:
        # Interpret missing components as 0
        major = int(parts[0]) if parts[0] else 0
        minor = int(parts[1]) if len(parts) > 1 and parts[1] else 0
        patch = int(parts[2]) if len(parts) > 2 and parts[2] else 0
    except ValueError:
        raise ValueError(f"Partial version components must be integers: '{text}'")

    # When parsing partial versions for range checks, we return a Version object
    # that represents the lowest bound implied by the partial spec (e.g., '1.2' -> 1.2.0).
    return Version(major, minor, patch)

def _evaluate_comparator(version: Version, spec_str: str) -> bool:
    """
    Evaluates a single comparator (e.g., '>=1.2', '^2.0', '=1.0.0').
    """
    spec_str = spec_str.strip()
    if not spec_str:
        return False

    op = ''
    value_str = spec_str

    if spec_str.startswith(('>=', '<=', '>', '<', '=')):
        if spec_str.startswith(('>=', '<=')):
            op = spec_str[:2]
            value_str = spec_str[2:].strip()
        else:
            op = spec_str[0]
            value_str = spec_str[1:].strip()
    elif spec_str.startswith('^') or spec_str.startswith('~'):
        op = spec_str[0]
        value_str = spec_str[1:].strip()
    else:
        # Bare version implies equality
        op = '='
        value_str = spec_str

    try:
        # Parse the target version from the spec string.
        # If the operator is '=', we check for partial matching capabilities.
        # Otherwise, we require a full SemVer format for operators like ^, ~, >, <.
        if op == '=':
            spec_version = _parse_partial_version(value_str)
        else:
            # For all other operators, we enforce full SemVer parsing as per standard range interpretation.
            spec_version = Version.parse(value_str)

    except ValueError as e:
        raise ValueError(f"Malformed version specification '{spec_str}': {e}")

    # 2. Apply range logic
    if op == '=':
        # Exact match (handles bare V and =V)
        return version == spec_version

    elif op in ('>=', '<='):
        # Standard comparison
        if op == '>=':
            return version >= spec_version
        else: # '<='
            return version <= spec_version

    elif op == '>':
        return version > spec_version

    elif op == '<':
        return version < spec_version

    elif op == '^':
        # Caret range logic (^X.Y.Z)
        major = spec_version.major
        minor = spec_version.minor
        patch = spec_version.patch

        # 1. Check lower bound: version >= spec_version
        lower_bound_ok = version >= spec_version
        if not lower_bound_ok:
            return False

        # 2. Check upper bound: version < next major boundary
        if major == 0 and minor == 0 and patch == 0:
            # ^0.0.0 is effectively >=0.0.0, but upper bound is 0.0.1 if we must bound it.
            # For practical purposes in ranges, this often means >=0.0.0. We use the smallest increment.
            upper_limit = Version(0, 0, 1) 
        elif major == 0:
            # ^0.Y.Z means < 0.(Y+1).0
            upper_limit = Version(0, minor + 1, 0)
        else:
            # ^X.Y.Z means < (X+1).0.0
            upper_limit = Version(major + 1, 0, 0)

        return version < upper_limit

    elif op == '~':
        # Tilde range logic (~X.Y.Z)
        major = spec_version.major
        minor = spec_version.minor
        patch = spec_version.patch

        # 1. Check lower bound: version >= spec_version
        lower_bound_ok = version >= spec_version
        if not lower_bound_ok:
            return False

        # 2. Check upper bound: version < next minor boundary
        if minor == 0 and patch == 0:
            # ~X.0.0 means < X.(0+1).0
            upper_limit = Version(major, 1, 0)
        elif patch == 0:
            # ~X.Y.0 means < X.(Y+1).0
            upper_limit = Version(major, minor + 1, 0)
        else:
            # ~X.Y.Z means < X.(Y+1).0
            upper_limit = Version(major, minor + 1, 0)

        return version < upper_limit

    return False # Should not be reached

def satisfies(version_or_str: Union[Version, str], spec: str) -> bool:
    """
    Checks if a given version satisfies all comparators in a specification string.
    """
    if not spec:
        raise ValueError("Specification string cannot be empty.")

    # 1. Normalize the input version
    if isinstance(version_or_str, str):
        try:
            version = Version.parse(version_or_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string provided: {e}")
    elif isinstance(version_or_str, Version):
        version = version_or_str
    else:
        raise TypeError("Input must be a Version object or a version string.")

    # 2. Split spec into individual comparators (separated by whitespace)
    comparators = spec.split()

    if not comparators:
        raise ValueError("Specification string contained no recognizable comparators.")

    # 3. Check every comparator
    for comparator in comparators:
        try:
            if not _evaluate_comparator(version, comparator):
                return False
        except ValueError:
            # Re-raise parsing errors from the helper function
            raise

    return True
