        if self.major != other.major:
            return self.major - other.major
        if self.minor != other.minor:
            return self.minor - other.minor
        if self.patch != other.patch:
            return self.patch - other.patch

        # Core versions are equal. Now compare pre-release status.
        has_pr1 = bool(self.prerelease)
        has_pr2 = bool(other.prerelease)

        if has_pr1 and not has_pr2:
            # A pre-release is lower than the final release of the same core
            return -1
        if not has_pr1 and has_pr2:
            return 1

        if has_pr1 and has_pr2:
            # Both have pre-release tags, compare identifiers
            pr_cmp = self._compare_prerelease(self.prerelease, other.prerelease)
            if pr_cmp != 0:
                return pr_cmp

        # If core versions and prerelease tags are equivalent (or both absent), they are equal
        return 0

