    """
    Evaluates a single comparator (e.g., '>=1.2', '^2.0', '=1.0.0').
    """
    spec_str = spec_str.strip()
    if not spec_str:
        return False

    op = ''
    value_str = spec_str

    if spec_str.startswith(('>=', '<=', '>', '<', '=')):
        if spec_str.startswith(('>=', '<=')):
            op = spec_str[:2]
            value_str = spec_str[2:].strip()
        else:
            op = spec_str[0]
            value_str = spec_str[1:].strip()
    elif spec_str.startswith('^') or spec_str.startswith('~'):
        op = spec_str[0]
        value_str = spec_str[1:].strip()
    else:
        # Bare version implies equality
        op = '='
        value_str = spec_str

    try:
        # Parse the target version from the spec string.
        # If the operator is '=', we check for partial matching capabilities.
        # Otherwise, we require a full SemVer format for operators like ^, ~, >, <.
        if op == '=':
            spec_version = _parse_partial_version(value_str)
        else:
            # For all other operators, we enforce full SemVer parsing as per standard range interpretation.
            spec_version = Version.parse(value_str)

    except ValueError as e:
        raise ValueError(f"Malformed version specification '{spec_str}': {e}")

    # 2. Apply range logic
    if op == '=':
        # Exact match (handles bare V and =V)
        return version == spec_version

    elif op in ('>=', '<='):
        # Standard comparison
        if op == '>=':
            return version >= spec_version
        else: # '<='
            return version <= spec_version

    elif op == '>':
        return version > spec_version

    elif op == '<':
        return version < spec_version

    elif op == '^':
        # Caret range logic (^X.Y.Z)
        major = spec_version.major
        minor = spec_version.minor
        patch = spec_version.patch

        # 1. Check lower bound: version >= spec_version
        lower_bound_ok = version >= spec_version
        if not lower_bound_ok:
            return False

        # 2. Check upper bound: version < next major boundary
        if major == 0 and minor == 0 and patch == 0:
            # ^0.0.0 is effectively >=0.0.0, but upper bound is 0.0.1 if we must bound it.
            # For practical purposes in ranges, this often means >=0.0.0. We use the smallest increment.
            upper_limit = Version(0, 0, 1) 
        elif major == 0:
            # ^0.Y.Z means < 0.(Y+1).0
            upper_limit = Version(0, minor + 1, 0)
        else:
            # ^X.Y.Z means < (X+1).0.0
            upper_limit = Version(major + 1, 0, 0)

        return version < upper_limit

    elif op == '~':
        # Tilde range logic (~X.Y.Z)
        major = spec_version.major
        minor = spec_version.minor
        patch = spec_version.patch

        # 1. Check lower bound: version >= spec_version
        lower_bound_ok = version >= spec_version
        if not lower_bound_ok:
            return False

        # 2. Check upper bound: version < next minor boundary
        if minor == 0 and patch == 0:
            # ~X.0.0 means < X.(0+1).0
            upper_limit = Version(major, 1, 0)
        elif patch == 0:
            # ~X.Y.0 means < X.(Y+1).0
            upper_limit = Version(major, minor + 1, 0)
        else:
            # ~X.Y.Z means < X.(Y+1).0
            upper_limit = Version(major, minor + 1, 0)

        return version < upper_limit

    return False # Should not be reached

def satisfies(version_or_str: Union[Version, str], spec: str) -> bool:
    """
    Checks if a given version satisfies all comparators in a specification string.
    """
    if not spec:
        raise ValueError("Specification string cannot be empty.")

    # 1. Normalize the input version
    if isinstance(version_or_str, str):
        try:
            version = Version.parse(version_or_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string provided: {e}")
    elif isinstance(version_or_str, Version):
        version = version_or_str
    else:
        raise TypeError("Input must be a Version object or a version string.")

    # 2. Split spec into individual comparators (separated by whitespace)
    comparators = spec.split()

    if not comparators:
        raise ValueError("Specification string contained no recognizable comparators.")

    # 3. Check every comparator
    for comparator in comparators:
        try:
            if not _evaluate_comparator(version, comparator):
                return False
        except ValueError:
            # Re-raise parsing errors from the helper function
            raise

    return True
