# Group 1: MAJOR, Group 2: MINOR, Group 3: PATCH
# Group 4: Full Pre-release string (optional)
# Group 5: Full Build string (optional)
FULL_SEMVER_REGEX = re.compile(
    rf"^{CORE_VERSION_REGEX}"  # Major.Minor.Patch
    rf"(?:{PRERELEASE_FULL_REGEX})?"  # Optional Pre-release
    rf"(?:{BUILD_FULL_REGEX})?$"  # Optional Build
