            prerelease_str = prerelease_full[1:]
            try:
                identifiers = _parse_identifiers(prerelease_str)
            except ValueError as e:
                raise ValueError(f"Invalid pre-release format: {e}")

            # Strict SemVer 2.0.0 validation: Numeric identifiers must not have leading zeros unless it is '0'
            for identifier in identifiers:
                if identifier.isdigit() and len(identifier) > 1 and identifier.startswith('0'):
                    raise ValueError(f"Pre-release numeric identifier '{identifier}' has illegal leading zero.")

            prerelease_identifiers = tuple(identifiers)

        build_identifiers: Tuple[str, ...] = ()
