        # 2. A version with a pre-release is lower than the same version without one.
        if not self.prerelease and other.prerelease:
            return 1 # self (stable) > other (prerelease)
        if self.prerelease and not other.prerelease:
            return -1 # self (prerelease) < other (stable)

        # 3. If both have pre-release or both are stable, compare identifiers
        if self.prerelease and other.prerelease:
            comparison = self._compare_identifiers(other.prerelease)
            if comparison != 0:
