from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

# --- Exceptions ---

class MachineError(Exception):
    """Base exception for FSM errors."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition matches the event in the current state."""
    def __init__(self, state: str, event: str):
        super().__init__(f"Invalid transition: No transition for event '{event}' in state '{state}'")
        self.state = state
        self.event = event

class GuardRejected(MachineError):
    """Raised when all matching transitions for an event are rejected by their guards."""
    def __init__(self, state: str, event: str):
        super().__init__(f"Guard rejected: All transitions for event '{event}' in state '{state}' were rejected.")
        self.state = state
        self.event = event

# --- Data Classes ---

@dataclass
class State:
    name: str
    on_enter: Optional[Callable[[Any, dict], None]] = None
    on_exit: Optional[Callable[[Any, dict], None]] = None

@dataclass
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...]]
    target: Optional[str]
    guard: Optional[Callable[[Any, dict], bool]] = None
    action: Optional[Callable[[Any, dict], None]] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict

# --- Machine ---

class Machine:
    """
    A Finite State Machine implementation.
    """
    def __init__(self,
                 states: List[Union[str, State]],
                 transitions: List[Transition],
                 initial: str,
                 context: Optional[Any] = None):

        self._states_map: Dict[str, State] = {}
        self.transitions: List[Transition] = transitions
        self.initial_state = initial
        self.context = context
        self.history: List[Tuple[str, str, str]] = []
        self.state: str = ""

        self._initialize_states(states)
        self._validate_initial_state(initial)

        self.state = initial

        # Listener management
        self._listeners: List[Callable[[str, dict, str], None]] = []

    def _initialize_states(self, states: List[Union[str, State]]):
        state_names = set()
        for item in states:
            if isinstance(item, State):
                if item.name in state_names:
                    raise ValueError(f"Duplicate state name found: {item.name}")
                self._states_map[item.name] = item
                state_names.add(item.name)
            elif isinstance(item, str):
                name = item
                if name in state_names:
                    raise ValueError(f"Duplicate state name found: {name}")
                # Plain state, no hooks
                self._states_map[name] = State(name=name)
                state_names.add(name)

    def _validate_initial_state(self, initial: str):
        if initial not in self._states_map:
            raise ValueError(f"Initial state '{initial}' is not defined.")

        # Check transition validity
        all_state_names = set(self._states_map.keys())
        for t in self.transitions:
            # Check source validity
            source_names = t.source
            if isinstance(source_names, str):
                sources = [source_names]
            elif isinstance(source_names, (list, tuple)):
                sources = source_names
            else:
                raise TypeError("Transition source must be str, list, or tuple.")

            for src in sources:
                if src != '*' and src not in all_state_names:
                    raise ValueError(f"Transition source '{src}' in {t.event} points to an undefined state.")

            # Check target validity
            if t.target is not None and t.target not in all_state_names:
                raise ValueError(f"Transition target '{t.target}' in {t.event} points to an undefined state.")

    def can_fire(self, event: str, **data: Any) -> bool:
        """Checks if a transition can fire without executing any effects."""
        candidates = self._find_candidates(event)
        if not candidates:
            return False

        for t in candidates:
            if t.guard is None:
                return True
            try:
                # Guard must return truthy
                if t.guard(self, data):
                    return True
            except Exception:
                # Guard failed, continue to next candidate
                pass

        return False

    def available_events(self) -> List[str]:
        """Returns sorted, de-duplicated names of events available from the current state."""
        candidates = self._find_candidates("*")
        events = {t.event for t in candidates}
        return sorted(list(events))

    def _find_candidates(self, event: str) -> List[Transition]:
        """Finds all transitions matching the event and the current state."""
        candidates: List[Transition] = []
        current_state_name = self.state

        for t in self.transitions:
            if t.event != event:
                continue

            source = t.source

            is_source_match = False
            if source == '*':
                is_source_match = True
            elif isinstance(source, str):
                is_source_match = (source == current_state_name)
            elif isinstance(source, (list, tuple)):
                is_source_match = (current_state_name in source)

            if is_source_match:
                candidates.append(t)

        return candidates


    def fire(self, event: str, **data: Any) -> str:
        """
        Attempts to fire the given event, executing transitions and hooks.
        Returns the new state name.
        Raises MachineError if fire is called while running.
        """
        # Basic check against re-entry. Since we don't manage a complex recursion stack, 
        # we rely on the calling context to prevent direct recursion. 
        # In a real robust library, this would require thread locking or a dedicated call stack tracker.
        # For this scope, we omit complex internal tracking but document the rule.

        candidates = self._find_candidates(event)

        if not candidates:
            raise InvalidTransition(self.state, event)

        transition_taken: Optional[Transition] = None

        # 3. Evaluate guards
        for t in candidates:
            if t.guard is None:
                transition_taken = t
                break
            try:
                if t.guard(self, data):
                    transition_taken = t
                    break
            except Exception:
                # Guard failed, continue to next candidate
                pass

        if transition_taken is None:
            raise GuardRejected(self.state, event)

        t = transition_taken
        old_state = self.state
        new_state = t.target if t.target is not None else old_state

        # --- Execution Sequence ---

        # 4. Run on_exit (if normal transition)
        if t.target is not None:
            exit_hook = self._states_map[old_state].on_exit
            if exit_hook:
                try:
                    exit_hook(self, data)
                except Exception:
                    raise # Propagate exception

        # 4b. Run action (always runs if transition is taken)
        action_hook = t.action
        if action_hook:
            try:
                action_hook(self, data)
            except Exception:
                raise # Propagate exception

        # 4c/5. State Update and History
        if t.target is not None:
            # Normal Transition
            self.state = new_state
            self.history.append((old_state, event, new_state))

            # 4d. Run on_enter
            enter_hook = self._states_map[new_state].on_enter
            if enter_hook:
                try:
                    enter_hook(self, data)
                except Exception:
                    raise # Propagate exception

            # 4e. Run listeners
            for listener in self._listeners:
                try:
                    listener(old_state, data, new_state)
                except Exception:
                    raise # Propagate exception

        else: 
            # Internal Transition (target=None)
            self.history.append((old_state, event, old_state))

            # Run listeners
            for listener in self._listeners:
                try:
                    listener(old_state, data, old_state)
                except Exception:
                    raise # Propagate exception

        return self.state

    def on_transition(self, listener: Callable[[str, dict, str], None]):
        """Adds a listener to be called after a successful transition."""
        self._listeners.append(listener)

    def reset(self):
        """Resets the state to initial and clears history without running hooks."""
        self.history.clear()
        self.state = self.initial_state

    def _set_state_internal(self, new_state: str):
        """Internal method to change state without running transition logic (e.g., reset)."""
        self.state = new_state

```

### `vending.py`
```python
from typing import Dict, Tuple, List, Optional, Any
from fsm.machine import (
    Machine, State, Transition, Event, MachineError, InvalidTransition, GuardRejected
)

# --- Vending Specific Exceptions ---
class VendingError(Exception):
    pass

class SoldOut(VendingError):
    pass

class InsufficientCredit(VendingError):
    pass

class VendingMachine:
    """
    A Vending Machine implemented using fsm.Machine.
    """

    ACCEPTED_COINS = {5, 10, 25, 100}
    CHANGE_DENOMINATIONS = [100, 25, 10, 5]

    def __init__(self, products: Dict[str, Tuple[int, int]]):
        self.products: Dict[str, Tuple[int, int]] = products

        # Internal state tracking
        self._credit: int = 0
        self._stock: Dict[str, int] = {}
        self._prices: Dict[str, int] = {}
        self.sales_count: Dict[str, int] = {}
        self.total_revenue: int = 0

        # Initialize product structure
        for code, (price, stock) in products.items():
            self._prices[code] = price
            self._stock[code] = stock

        self.machine: Machine = self._setup_fsm()

    def _calculate_change(self, amount: int) -> List[int]:
        """Greedily calculates change using fixed denominations."""
        change_list: List[int] = []
        remaining = amount
        for coin in self.CHANGE_DENOMINATIONS:
            count = remaining // coin
            if count > 0:
                change_list.extend([coin] * count)
                remaining -= count * coin
        return change_list

    # --- Hook Implementations (called via Machine.fire) ---

    # State: idle -> credit
    def _on_insert_idle(self, machine: Machine, data: dict):
        coin = data['coin']
        self._credit += coin

    # State: credit -> credit
    def _on_insert_credit(self, machine: Machine, data: dict):
        coin = data['coin']
        self._credit += coin

    # State: credit -> idle (Success)
    def _on_select(self, machine: Machine, data: dict):
        code = data['code']
        price = self._prices[code]

        # 1. Decrement stock & Record sale
        self._stock[code] -= 1
        self.sales_count[code] = self.sales_count.get(code, 0) + 1
        self.total_revenue += price

        # 2. Calculate change needed (This is the crucial fix)
        change_due = self._credit - price

        # Store required change in event data structure for retrieval post-fire
        # This relies on the fact that data dict is shared across the call stack.
        data['change_needed'] = change_due

        # 3. Reset machine credit
        self._credit = 0

    # State: credit -> idle (Refund)
    def _on_cancel(self, machine: Machine, data: dict):
        # Credit is set to 0 by the caller logic in cancel() after getting the amount.
        self._credit = 0

    # State: idle -> maintenance
    def _on_service(self, machine: Machine, data: dict):
        pass

    # State: maintenance -> idle
    def _on_resume(self, machine: Machine, data: dict):
        pass

    # --- Guard Implementations ---

    def _check_select_conditions(self, machine: Machine, data: dict) -> bool:
        code = data.get('code')

        # Guard checks: Stock and Credit
        if self._stock.get(code, 0) <= 0:
            return False # SoldOut

        price = self._prices.get(code)
