from typing import Dict, Tuple, List, Optional, Any
from fsm.machine import (
    Machine, State, Transition, Event, MachineError, InvalidTransition, GuardRejected
)

# --- Vending Specific Exceptions ---
class VendingError(Exception):
    pass

class SoldOut(VendingError):
    pass

class InsufficientCredit(VendingError):
    pass

class VendingMachine:
    """
    A Vending Machine implemented using fsm.Machine.
    """

    ACCEPTED_COINS = {5, 10, 25, 100}
    CHANGE_DENOMINATIONS = [100, 25, 10, 5]

    def __init__(self, products: Dict[str, Tuple[int, int]]):
        self.products: Dict[str, Tuple[int, int]] = products

        # Internal state tracking
        self._credit: int = 0
        self._stock: Dict[str, int] = {}
        self._prices: Dict[str, int] = {}
        self.sales_count: Dict[str, int] = {}
        self.total_revenue: int = 0

        # Initialize product structure
        for code, (price, stock) in products.items():
            self._prices[code] = price
            self._stock[code] = stock

        self.machine: Machine = self._setup_fsm()

    def _calculate_change(self, amount: int) -> List[int]:
        """Greedily calculates change using fixed denominations."""
        change_list: List[int] = []
        remaining = amount
        for coin in self.CHANGE_DENOMINATIONS:
            count = remaining // coin
            if count > 0:
                change_list.extend([coin] * count)
                remaining -= count * coin
        return change_list

    # --- Hook Implementations (called via Machine.fire) ---

    # State: idle -> credit
    def _on_insert_idle(self, machine: Machine, data: dict):
        coin = data['coin']
        self._credit += coin

    # State: credit -> credit
    def _on_insert_credit(self, machine: Machine, data: dict):
        coin = data['coin']
        self._credit += coin

    # State: credit -> idle (Success)
    def _on_select(self, machine: Machine, data: dict):
        code = data['code']
        price = self._prices[code]

        # 1. Decrement stock & Record sale
        self._stock[code] -= 1
        self.sales_count[code] = self.sales_count.get(code, 0) + 1
        self.total_revenue += price

        # 2. Calculate change needed (This is the crucial fix)
        change_due = self._credit - price

        # Store required change in event data structure for retrieval post-fire
        # This relies on the fact that data dict is shared across the call stack.
        data['change_needed'] = change_due

        # 3. Reset machine credit
        self._credit = 0

    # State: credit -> idle (Refund)
    def _on_cancel(self, machine: Machine, data: dict):
        # Credit is set to 0 by the caller logic in cancel() after getting the amount.
        self._credit = 0

    # State: idle -> maintenance
    def _on_service(self, machine: Machine, data: dict):
        pass

    # State: maintenance -> idle
    def _on_resume(self, machine: Machine, data: dict):
        pass

    # --- Guard Implementations ---

    def _check_select_conditions(self, machine: Machine, data: dict) -> bool:
        code = data.get('code')

        # Guard checks: Stock and Credit
        if self._stock.get(code, 0) <= 0:
            return False # SoldOut

        price = self._prices.get(code)
        if price is None:
            # Should be caught by InvalidTransition earlier if FSM is set up correctly,
            # but guard must be safe.
            return False 

        if self._credit < price:
            return False # InsufficientCredit

        return True # All checks passed

    def _setup_fsm(self) -> Machine:
        """Configures and initializes the FSM."""

        # Define states using State objects for hooks
        idle_state = State(name='idle')
        credit_state = State(name='credit')
        maintenance_state = State(name='maintenance')

        transitions = [
            # Insert Coin
            Transition(event="insert", source="idle", target="credit", action=self._on_insert_idle),
            Transition(event="insert", source="credit", target="credit", action=self._on_insert_credit),

            # Select Product (Uses patched action)
            Transition(event="select", source="credit", target="idle", guard=self._check_select_conditions, action=self._on_select),

            # Cancel (Refund)
            Transition(event="cancel", source="credit", target="idle", action=self._on_cancel),

            # Service Machine
            Transition(event="service", source="idle", target="maintenance", action=self._on_service),

            # Resume Machine
            Transition(event="resume", source="maintenance", target="idle", action=self._on_resume),
        ]

        machine = Machine(
            states=[idle_state, credit_state, maintenance_state],
            transitions=transitions,
            initial='idle',
            context=self
        )
        return machine

    # --- Public Methods ---

    def insert(self, coin: int) -> int:
        """Adds coin to credit, moves to 'credit'."""
        if coin not in self.ACCEPTED_COINS:
            raise ValueError("Coin not accepted.")

        try:
            # FSM handles state checks automatically
            self.machine.fire("insert", coin=coin)
            return self._credit
        except InvalidTransition:
            # If state is 'maintenance', InvalidTransition is correctly raised by FSM
            raise

    def select(self, code: str) -> List[int]:
        """Sells one unit, returns change, resets credit to 0, moves to idle."""

        # Pre-check for product existence (must happen before FSM calls, as FSM only checks state/guards)
        if code not in self._prices:
            raise KeyError(f"Product code '{code}' not found.")

        # We rely on the FSM to raise InvalidTransition if state is not 'credit'
        try:
            # Fire the transition. The _on_select hook populates data['change_needed'].
            new_state = self.machine.fire("select", code=code)

            if new_state != 'idle':
                 # Sanity check, should always transition to idle on success
                 raise RuntimeError("Select transition did not lead to idle state.")

            # Retrieve change calculated by the hook
            change_needed = self.machine.context.context.data.get('change_needed')

            if change_needed is None:
                # Should not happen if FSM executed successfully
                return [] 

            # Dispense change
            return self._calculate_change(change_needed)

        except (InvalidTransition, GuardRejected) as e:
            # Failed transition, state/credit/stock/revenue are unchanged (or only partially modified by guards)
            raise e

    def cancel(self) -> List[int]:
        """Refunds entire credit, resets credit to 0, moves to idle."""
        refund_amount = self._credit

        try:
            # Fire the transition. _on_cancel ensures self._credit becomes 0.
            self.machine.fire("cancel")
            return self._calculate_change(refund_amount)
        except (InvalidTransition, GuardRejected) as e:
            raise e

    def service(self) -> None:
        """Enters maintenance from idle."""
        # Relies entirely on FSM to check if state is 'idle'
        try:
            self.machine.fire("service")
        except InvalidTransition:
            # Re-raise to satisfy requirement that non-allowed operations raise InvalidTransition
            raise

    def restock(self, code: str, qty: int, price: Optional[int] = None) -> None:
        """Adds stock in maintenance mode."""
        if qty < 1:
            raise ValueError("Quantity must be >= 1.")

        # Check if FSM allows 'restock' in current state ('maintenance')
        # Since FSM doesn't inherently know about 'restock', we must check state explicitly, 
        # or add a transition for it. As per prompt, we check state first.
        if self.machine.state != 'maintenance':
            raise InvalidTransition(self.machine.state, "restock")

        if code not in self._prices and price is None:
            raise KeyError(f"Price must be provided for new product code '{code}'.")

        # Perform business logic regardless of FSM transition (since FSM only transitions TO maintenance)
        self._stock[code] = self._stock.get(code, 0) + qty

        if code not in self._prices and price is not None:
