from dataclasses import dataclass, field
from datetime import date, timedelta
from typing import Optional, Dict, List, Tuple
from .catalog import Catalog
from .fines import POLICY, due_date, fine_for, HOLD_PICKUP_DAYS

# --- Exceptions ---

class LoanError(Exception):
    pass

class Blocked(LoanError):
    pass

class DuplicateLoan(LoanError):
    pass

class LimitReached(LoanError):
    pass

class NotAvailable(LoanError):
    pass

class RenewalRefused(LoanError):
    pass

# --- Data Structures ---

@dataclass(frozen=True)
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: Optional[date] = None
    fine: int = 0

    # Helper for internal state replacement (since it's frozen)
    def _replace(self, **kwargs):
        return Loan(**self.__dict__, **kwargs)

# --- Library Implementation ---

class Library:
    def __init__(self, catalog: Catalog, clock):
        self.catalog = catalog
        self.clock = clock

        self._loans: Dict[int, Loan] = {}
        self._next_loan_id: int = 1
        self._member_balances: Dict[str, int] = {} # member_id -> total fine in cents

        # Hold tracking: isbn -> list of hold requests (member_id, position)
        self._waiting_holds: Dict[str, List[Tuple[str, int]]] = {} 
        # Hold status tracking: member_id -> isbn -> ('ready' | 'waiting', data)
        self._hold_status: Dict[str, Dict[str, Tuple[str, any]]] = {} 
        # Ready holds: isbn -> list of (deadline: date, member_id)
        self._ready_holds: Dict[str, List[Tuple[date, str]]] = {}

    def _apply_daily_expirations(self, today: date):
        """
        Processes holds that expire today or before. 
        This must run at the start of any operation to ensure state consistency.
        """

        # 1. Check ready holds for expiry
        for isbn in list(self._ready_holds.keys()):
            ready_holds_today = []
            expired_holds = []

            # Sort by deadline to process chronologically
            sorted_ready_holds = sorted(self._ready_holds[isbn], key=lambda x: x[0])

            for deadline, member_id in sorted_ready_holds:
                if deadline < today:
                    expired_holds.append((deadline, member_id))
                else:
                    ready_holds_today.append((deadline, member_id))

            self._ready_holds[isbn] = ready_holds_today

            for _, member_id in expired_holds:
                # Hold expired, pass copy to next waiting hold or release

                # Remove from hold status
                if isbn in self._hold_status.get(member_id, {}):
                    del self._hold_status[member_id][isbn]

                # Check waiting queue
                if isbn in self._waiting_holds and self._waiting_holds[isbn]:
                    # Set aside copy for the next waiting hold
                    next_member_id, _ = self._waiting_holds[isbn].pop(0)

                    # The next hold becomes ready with deadline: today + HOLD_PICKUP_DAYS
                    new_deadline = today + timedelta(days=HOLD_PICKUP_DAYS)

                    self._ready_holds[isbn].append((new_deadline, next_member_id))

                    # Update hold status for the newly ready hold
                    if next_member_id not in self._hold_status:
                        self._hold_status[next_member_id] = {}
                    self._hold_status[next_member_id][isbn] = ('ready', new_deadline)
                else:
                    # No waiting holds, copy becomes available
                    pass

    def _validate_member_and_isbn(self, member_id, isbn):
        try:
            self.catalog.member(member_id)
            self.catalog.book(isbn)
        except KeyError as e:
            raise KeyError(f"Entity not found: {e}")

    def checkout(self, member_id: str, isbn: str) -> Loan:
        today = self.clock()
        self._apply_daily_expirations(today)
        self._validate_member_and_isbn(member_id, isbn)

        member = self.catalog.member(member_id)
        policy = POLICY[member.kind]

        # 1. Blocked check (fine balance > 0)
        if self._member_balances.get(member_id, 0) > 0:
            raise Blocked(f"Member {member_id} has outstanding fines.")

        # 2. DuplicateLoan check
        active_loans = self.loans(member_id)
        if any(loan.isbn == isbn for loan in active_loans):
            raise DuplicateLoan("Member already has this item on loan.")

        # 3. LimitReached check
        if len(active_loans) >= policy.max_loans:
            raise LimitReached(f"Member has reached maximum loan limit of {policy.max_loans}.")

        # Check for ready hold first (prioritized checkout)
        hold_info = self._hold_status.get(member_id, {}).get(isbn)

        is_ready_hold = False
        if hold_info and hold_info[0] == 'ready':
            # Checkout uses the set-aside copy
            self._ready_holds[isbn] = [
                (d, mid) for d, mid in self._ready_holds.get(isbn, []) 
                if mid != member_id
            ]

            # Remove hold status
            if member_id in self._hold_status and isbn in self._hold_status[member_id]:
                 del self._hold_status[member_id][isbn]
            is_ready_hold = True

        # 4. NotAvailable check (If no ready hold, check general availability)
        available = self.available(isbn)
        if not is_ready_hold and available <= 0:
            raise NotAvailable(f"No copies of ISBN {isbn} are available.")

        # Remove waiting hold if present (checkout cancels waiting holds)
        if isbn in self._waiting_holds:
            initial_count = len(self._waiting_holds[isbn])
            self._waiting_holds[isbn] = [
                (mid, pos) for mid, pos in self._waiting_holds[isbn] if mid != member_id
            ]
            if len(self._waiting_holds[isbn]) < initial_count:
                 # If we successfully removed the hold, clean up status map
                 if member_id in self._hold_status and isbn in self._hold_status[member_id]:
                    del self._hold_status[member_id][isbn]


        # Create and record loan
        loan_days = POLICY[member.kind].loan_days
        due = due_date(today, loan_days)

        new_loan = Loan(
            loan_id=self._next_loan_id,
            member_id=member_id,
            isbn=isbn,
            start=today,
            due=due,
            renewals=0
        )
        self._loans[self._next_loan_id] = new_loan
        self._next_loan_id += 1

        return new_loan

    def place_hold(self, member_id: str, isbn: str) -> int:
        today = self.clock()
        self._apply_daily_expirations(today)
        self._validate_member_and_isbn(member_id, isbn)

        member = self.catalog.member(member_id)

        # Check if already on loan
        if any(l.isbn == isbn and l.member_id == member_id and l.returned is None for l in self._loans.values()):
            raise DuplicateLoan("Member already has this item on loan.")

        # Check if already has a hold
        if isbn in self._hold_status.get(member_id, {}):
            raise DuplicateLoan("Member already has a hold on this item.")

        available = self.available(isbn)
        if available > 0:
            raise LoanError("No copies are currently available to place a hold on.")

        # Add to waiting queue
        if isbn not in self._waiting_holds:
            self._waiting_holds[isbn] = []

        # Position is based on current queue size
        position = len(self._waiting_holds[isbn]) + 1
        self._waiting_holds[isbn].append((member_id, position))

        # Update hold status (initially waiting)
        if member_id not in self._hold_status:
            self._hold_status[member_id] = {}
        self._hold_status[member_id][isbn] = ('waiting', position)

        return position

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        today = self.clock()
        self._apply_daily_expirations(today)
        self._validate_member_and_isbn(member_id, isbn)

        if isbn not in self._hold_status.get(member_id, {}):
            raise KeyError(f"Member {member_id} has no hold on ISBN {isbn}.")

        hold_type, data = self._hold_status[member_id][isbn]

        if hold_type == 'waiting':
            # Remove from waiting queue
            if isbn in self._waiting_holds:
                original_queue = self._waiting_holds[isbn]
                new_queue = [item for item in original_queue if item[0] != member_id]

                if len(new_queue) < len(original_queue):
                    self._waiting_holds[isbn] = new_queue
                    # Clean up status map
                    del self._hold_status[member_id][isbn]
                else:
                     # Should not happen if hold_status is correct
                     raise KeyError(f"Could not find hold for {member_id} on {isbn} in waiting queue.")

        elif hold_type == 'ready':
            # Hold cancelled, pass copy to next waiting hold (as if expired)
            if isbn in self._ready_holds:
                self._ready_holds[isbn] = [
                    (d, mid) for d, mid in self._ready_holds[isbn] if mid != member_id
                ]

            # Remove from hold status
            del self._hold_status[member_id][isbn]

            # Logic for expiry: next waiting hold becomes ready today + pickup days
            if isbn in self._waiting_holds and self._waiting_holds[isbn]:
                next_member_id, _ = self._waiting_holds[isbn].pop(0)
                new_deadline = today + timedelta(days=HOLD_PICKUP_DAYS)

                self._ready_holds.setdefault(isbn, []).append((new_deadline, next_member_id))

                if next_member_id not in self._hold_status:
                    self._hold_status[next_member_id] = {}
                self._hold_status[next_member_id][isbn] = ('ready', new_deadline)

    def holds(self, isbn: str) -> list[str]:
        today = self.clock()
        self._apply_daily_expirations(today)
        if isbn not in self._waiting_holds:
            return []

        return [mid for mid, _ in self._waiting_holds[isbn]]

    def hold_status(self, member_id: str, isbn: str) -> Tuple[str, any]:
        today = self.clock()
        self._apply_daily_expirations(today)

        if member_id not in self._hold_status or isbn not in self._hold_status[member_id]:
            raise KeyError(f"No hold found for member {member_id} on ISBN {isbn}.")

        hold_info = self._hold_status[member_id][isbn]
        hold_type, data = hold_info

        if hold_type == 'ready':
            deadline = data
            return ('ready', deadline)
        elif hold_type == 'waiting':
            position = data
            return ('waiting', position)

        raise RuntimeError("Invalid hold status.")


    def renew(self, loan_id: int) -> date:
        today = self.clock()
        self._apply_daily_expirations(today)

        if loan_id not in self._loans:
            raise KeyError(f"Loan ID {loan_id} not found.")

        loan = self._loans[loan_id]
        if loan.returned is not None:
            raise LoanError("Cannot renew a returned loan.")

        member = self.catalog.member(loan.member_id)
        policy = POLICY[member.kind]

        # 1. Hold check (waiting or ready)
        if loan.isbn in self._waiting_holds or loan.isbn in self._hold_status:
            raise RenewalRefused("Cannot renew: There is a hold on this item.")

        # 2. Renewal count check
        if loan.renewals >= policy.renewals:
            raise RenewalRefused("Maximum number of renewals reached.")

        # Successful renewal
        new_due = due_date(loan.due, policy.loan_days)

        # Update loan state by replacing the frozen object
        self._loans[loan_id] = loan._replace(due=new_due, renewals=loan.renewals + 1)
        return new_due

    def checkin(self, loan_id: int) -> int:
        today = self.clock()
        self._apply_daily_expirations(today)

        if loan_id not in self._loans:
            raise KeyError(f"Loan ID {loan_id} not found.")

        loan = self._loans[loan_id]
        if loan.returned is not None:
            raise LoanError("Loan has already been returned.")

        member = self.catalog.member(loan.member_id)
        fine = fine_for(member.kind, loan.due, today)

        # Update loan state
        self._loans[loan_id] = loan._replace(returned=today, fine=fine)

        # Add fine to member balance
        self._member_balances[loan.member_id] = self._member_balances.get(loan.member_id, 0) + fine

        # Set aside for waiting hold
        if loan.isbn in self._waiting_holds and self._waiting_holds[loan.isbn]:
            # Copy is set aside for the earliest waiting hold
            next_member_id, _ = self._waiting_holds[loan.isbn].pop(0)

            new_deadline = today + timedelta(days=HOLD_PICKUP_DAYS)

            self._ready_holds.setdefault(loan.isbn, []).append((new_deadline, next_member_id))

            # Update hold status for the newly ready hold
            if next_member_id not in self._hold_status:
                self._hold_status[next_member_id] = {}
            self._hold_status[next_member_id][loan.isbn] = ('ready', new_deadline)

        return fine

    def accrued_fine(self, loan_id: int) -> int:
        if loan_id not in self._loans:
            raise KeyError(f"Loan ID {loan_id} not found.")
        loan = self._loans[loan_id]
        if loan.returned:
            return loan.fine
        else:
            member = self.catalog.member(loan.member_id)
            return fine_for(member.kind, loan.due, self.clock())

    def balance(self, member_id: str) -> int:
        return self._member_balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")

        current_balance = self.balance(member_id)
        if amount > current_balance:
            raise ValueError("Payment amount exceeds outstanding balance.")

        new_balance = current_balance - amount
        self._member_balances[member_id] = new_balance
        return new_balance

    def loans(self, member_id: str) -> List[Loan]:
        today = self.clock()
        active_loans = []
        for loan in self._loans.values():
            if loan.member_id == member_id and loan.returned is None:
                active_loans.append(loan)

        # Sort by due date, then loan id
        active_loans.sort(key=lambda l: (l.due, l.loan_id))
        return active_loans

    def overdue(self) -> List[Loan]:
        today = self.clock()
        overdue_loans = []
        for loan in self._loans.values():
            if loan.returned is None and loan.due < today:
                overdue_loans.append(loan)

        # Sort by due date, then loan id
        overdue_loans.sort(key=lambda l: (l.due, l.loan_id))
        return overdue_loans

    # --- Helper methods for availability calculation ---

    def available(self, isbn: str) -> int:
        """Total copies - active loans - ready holds."""
        book = self.catalog.book(isbn)
        total_copies = book.copies

        # Count active loans
        active_loans_count = sum(1 for loan in self._loans.values() 
                                 if loan.isbn == isbn and loan.returned is None)

        # Count ready holds (a copy is set aside if it's ready)
        ready_holds_count = len(self._ready_holds.get(isbn, []))

        return total_copies - active_loans_count - ready_holds_count

