import re
from typing import Any, Dict, Set, Union, List
from collections import deque

class FormulaError(ValueError):
    """Raised when a formula is syntactically or structurally invalid."""
    pass

class ErrorValue(str):
    """Represents an error value in the sheet."""
    pass

ERROR_GENERIC = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- AST Node Definitions ---

class NumberNode:
    def __init__(self, value: Union[int, float]):
        self.value = value
    def __repr__(self):
        return f"Num({self.value})"

class RefNode:
    def __init__(self, name: str):
        self.name = name.upper()
    def __repr__(self):
        return f"Ref({self.name})"

class BinOpNode:
    def __init__(self, left: Any, op: str, right: Any):
        self.left = left
        self.op = op
        self.right = right
    def __repr__(self):
        return f"BinOp({self.left} {self.op} {self.right})"

class UnaryOpNode:
    def __init__(self, op: str, operand: Any):
        self.op = op
        self.operand = operand
    def __repr__(self):
        return f"UnOp({self.op} {self.operand})"

# --- Tokenizer ---

TOKEN_REGEX = r'\s*([+-]?\s*\d+(\.\d*)?|\b[A-Z]+\d+\b|\(|\)|[+\-*/])\s*'

def tokenize(source: str) -> List[str]:
    tokens = []
    # Tokenize while respecting structure and discarding whitespace
    for match in re.finditer(TOKEN_REGEX, source):
        token = match.group(1).strip()
        if token:
            tokens.append(token)
    return tokens

# --- Parser (Recursive Descent based on Precedence) ---

class Parser:
    def __init__(self, tokens: List[str]):
        self.tokens = deque(tokens)

    def eat(self, expected: str = None):
        if not self.tokens:
            raise FormulaError("Unexpected end of expression.")
        token = self.tokens.popleft()
        if expected and token != expected:
            raise FormulaError(f"Expected '{expected}' but got '{token}'.")
        return token

    def parse(self) -> Any:
        ast = self._expression()
        if self.tokens:
            raise FormulaError(f"Unexpected tokens remaining: {list(self.tokens)}")
        return ast

    def _primary(self) -> Any:
        token = self.tokens[0] if self.tokens else None

        # Number literal
        if re.fullmatch(r'[+-]?\d+(\.\d*)?', token):
            self.eat()
            if '.' in token:
                return NumberNode(float(token))
            return NumberNode(int(token))

        # Reference (Letters followed by digits)
        if re.fullmatch(r'[A-Z]+\d+', token.upper()):
            self.eat()
            return RefNode(token.upper())

        # Parenthesized expression
        if token == '(':
            self.eat('(')
            node = self._expression()
            self.eat(')')
            return node

        # Unary sign handling
        if token in ('+', '-'):
            self.eat() # Consume unary sign
            operand = self._primary()
            op_char = token
            if op_char == '+':
                # Unary + is identity, but we keep it for structure
                return operand
            return UnaryOpNode(op_char, operand)

        raise FormulaError(f"Unexpected token in primary expression: {token}")

    def _unary(self) -> Any:
        # Unary sign is handled within _primary for simplicity in this implementation
        return self._primary()

    def _factor(self) -> Any:
        # Since unary binds tightest, it is handled by _primary which calls _unary implicitly
        return self._primary()

    # Operator Precedence Parsing:
    # Expr (+/-) Term
    def _expression(self) -> Any:
        node = self._term()
        while self.tokens and self.tokens[0] in ('+', '-'):
            op = self.eat()
            right = self._term()
            node = BinOpNode(node, op, right)
        return node

    # Term (* /) Factor
    def _term(self) -> Any:
        node = self._factor()
        while self.tokens and self.tokens[0] in ('*', '/'):
            op = self.eat()
            right = self._factor()
            node = BinOpNode(node, op, right)
        return node

def parse_formula(source: str) -> Any:
    """
    Parses the text after '=' into a syntax tree.
    """
    source = source.strip()
    if not source:
        raise FormulaError("Formula input cannot be empty.")

    tokens = tokenize(source)
    if not tokens:
        raise FormulaError("Formula contains no recognizable tokens.")

    parser = Parser(tokens)
    return parser.parse()

# --- Reference Extraction ---

def references(tree: Any) -> Set[str]:
    """Extracts all cell references from the formula's syntax tree."""
    refs: Set[str] = set()
    if isinstance(tree, RefNode):
        return {tree.name}
    elif isinstance(tree, BinOpNode):
        refs.update(references(tree.left))
        refs.update(references(tree.right))
    elif isinstance(tree, UnaryOpNode):
        refs.update(references(tree.operand))
    else:
        pass
    return refs

# --- Evaluation ---

def evaluate(tree: Any, lookup: callable) -> Union[int, float, str, ErrorValue, None]:
    """Computes the formula's value."""

    def apply_op(left_val, op, right_val):
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return left_val if isinstance(left_val, ErrorValue) else right_val

        if isinstance(left_val, str) or isinstance(right_val, str):
            # Text interaction with math
            return ERROR_GENERIC

        # Arithmetic evaluation
        if op == '+': return left_val + right_val
        if op == '-': return left_val - right_val
        if op == '*': return left_val * right_val
        if op == '/':
            if right_val == 0:
                return ERROR_GENERIC
            return left_val / right_val
        raise FormulaError("Unknown operator")

    def resolve_operand(node: Any) -> Any:
        if isinstance(node, NumberNode):
            return node.value
        elif isinstance(node, RefNode):
            ref_name = node.name
            value = lookup(ref_name)

            # Rule 2: Reference handling
            if value is None:
                return 0
            if isinstance(value, str) and not (isinstance(value, ErrorValue)):
                 # If it's text, the *result* of the formula containing this ref is text (if it's only a ref)
                 # For intermediate evaluation, we must return the value.
                 # This specific rule implies if the *entire* formula is just a reference, it returns text.
                 # We handle this in the main evaluation loop context. Here, we return the value.
                 return value # Will cause ERROR_GENERIC if combined with math later, which is correct.
            return value
        elif isinstance(node, UnaryOpNode):
            operand_val = resolve_operand(node.operand)
            if node.op == '+':
                return operand_val
            elif node.op == '-':
                # Unary minus: Convert to additive structure if possible
                if isinstance(operand_val, (int, float)):
                    return -operand_val
                return ERROR_GENERIC

        elif isinstance(node, BinOpNode):
            left_val = resolve_operand(node.left)
            right_val = resolve_operand(node.right)
            return apply_op(left_val, node.op, right_val)

        raise FormulaError("Unknown node type during evaluation")


    # Special handling for Rule 2: If the tree is only a reference node.
    if isinstance(tree, RefNode):
        # This is a formula consisting ONLY of a reference.
        value = lookup(tree.name)
        if value is None:
            return None # Empty cell evaluates to None
        return value # Returns text unchanged (Rule 2)

    try:
        result = resolve_operand(tree)

        # Final type enforcement (Rule 1/4)
        if isinstance(result, float) and result.is_integer():
            return int(result)
        return result

    except FormulaError:
        return ERROR_GENERIC
    except Exception:
        # Catching potential type errors during arithmetic propagation
        return ERROR_GENERIC
