from typing import Dict, Any, List, Optional, Set
from .graph import DependencyGraph
from .formula import (
    parse_formula, references, evaluate, FormulaError, ERROR_CYCLE, ERROR_GENERIC, ErrorValue
)

MAX_COL = 26
MAX_ROW = 999

class Sheet:
    def __init__(self):
        self._raw_data: Dict[str, str] = {}
        self._values: Dict[str, Any] = {}
        self._formula_trees: Dict[str, Any] = {}
        self._is_formula: Dict[str, bool] = {}

        self.graph = DependencyGraph()
        self.evaluations = 0

    def _validate_name(self, name: str):
        """Validates cell name format."""
        name = name.upper()
        if not name:
            raise ValueError("Cell name cannot be empty.")

        col_part = ""
        row_part = ""

        # Column letters (A-Z)
        i = 0
        while i < len(name) and 'A' <= name[i] <= 'Z':
            col_part += name[i]
            i += 1

        row_part = name[i:]

        if not row_part or not row_part.isdigit():
            raise ValueError(f"Invalid cell name format: {name}")

        row_num = int(row_part)

        if not (1 <= row_num <= MAX_ROW):
            raise ValueError(f"Row number {row_num} out of range (1-{MAX_ROW}).")

        if len(col_part) > MAX_COL:
             raise ValueError("Too many columns.")

        if len(row_part) > 1 and row_part.startswith('0'):
             raise ValueError("Row number cannot have leading zeros.")

        return name

    def _get_cells_in_row_major_order(self) -> List[str]:
        """Generates all valid cell names in row-major order (Row then Column)."""
