from typing import Dict, Set, Iterable

class DependencyGraph:
    def __init__(self):
        self._precedents: Dict[str, Set[str]] = {}
        self._dependents: Dict[str, Set[str]] = {}
        self._known_cells: Set[str] = set()

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Replaces the precedents for a cell."""
        new_precedents = set(precedents)

        # Check if the cell was previously tracked
        was_known = cell in self._known_cells

        self._precedents[cell] = new_precedents

        # Rebuild dependents structure incrementally or fully
        if was_known or new_precedents:
             self._rebuild_dependents(cell)
             self._known_cells.add(cell)


    def _rebuild_dependents(self, changed_cell: str):
        """Rebuilds the dependents structure for all known cells."""
        # Initialize/update known dependents
        if changed_cell not in self._dependents:
            self._dependents[changed_cell] = set()

        # Full rebuild is safest for ensuring consistency after a major dependency change
        new_dependents: Dict[str, Set[str]] = {c: set() for c in self._known_cells}

        for cell, preds in self._precedents.items():
            for pred in preds:
                if pred in self._known_cells:
                    new_dependents[pred].add(cell)
        self._dependents = new_dependents


    def precedents(self, cell: str) -> Set[str]:
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or through other cells.
        Includes 'cell' itself ONLY if it is on a cycle.
        """
        if cell not in self._known_cells:
            return set()

        # BFS to find all direct/indirect dependents
        queue = deque(self.dependents.get(cell, set()))
        all_deps = set()
        visited = set(queue)

        while queue:
            current = queue.popleft()
            all_deps.add(current)

            for next_dep in self.dependents.get(current, set()):
                if next_dep not in visited:
                    visited.add(next_dep)
                    queue.append(next_dep)

        # Rule: Contains cell itself only if on a cycle.
        if cell in self.cycle_cells():
            all_deps.add(cell)

        return all_deps

    def cycle_cells(self) -> Set[str]:
        """Finds all cells involved in a cycle using DFS."""
        visited: Set[str] = set()
        recursion_stack: Set[str] = set()
        cycle_nodes: Set[str] = set()

        def dfs(node: str) -> bool:
            visited.add(node)
            recursion_stack.add(node)

            for neighbor in self.precedents.get(node, set()):
                if neighbor not in self._known_cells:
                    continue

                if neighbor in recursion_stack:
                    # Cycle detected. All nodes currently on the stack up to 'neighbor' are part of a cycle.
                    # For simplicity, we mark both the node and the neighbor involved.
                    cycle_nodes.add(neighbor)
                    cycle_nodes.add(node)
                    return True

                if neighbor not in visited:
                    if dfs(neighbor):
                        cycle_nodes.add(node)
                        return True

            recursion_stack.remove(node)
            return False

        for cell in self._known_cells:
            if cell not in visited:
                dfs(cell)

        return cycle_nodes
