        self.left = left
        self.op = op
        self.right = right

class UnaryOp(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op
        self.operand = operand

class ParenthesizedExpression(FormulaNode):
    def __init__(self, expr: FormulaNode):
        self.expr = expr

# --- Parsing Logic ---

def _tokenize(source: str) -> List[str]:
    """Splits the formula string into meaningful tokens."""
    # Tokens: numbers (int/float), operators (+, -, *, /), parens, references (letters+digits)
    # Whitespace is ignored between tokens.
    token_specification = [
        ('NUMBER', r'\d+(\.\d*)?'),
        ('REFERENCE', r'[a-zA-Z]+\d+'),
        ('OP', r'[+\-*/()]'),
        ('SKIP', r'\s+'),
        ('MISMATCH', r'.'),
    ]
    tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_specification)

    tokens = []
    for mo in re.finditer(tok_regex, source):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Unexpected character: {value}")
        tokens.append((kind, value))
    return tokens

def _parse_expression(tokens: List[tuple[str, str]], start_index: int) -> tuple[FormulaNode, int]:
    """Parses expr: term {(+ | -) term}"""
    left_node, current_index = _parse_term(tokens, start_index)

    while current_index < len(tokens) and tokens[current_index][1] in ('+', '-'):
        op_token = tokens[current_index]
        op = op_token[1]
        current_index += 1

        right_node, next_index = _parse_term(tokens, current_index)

        left_node = BinaryOp(left_node, op, right_node)
        current_index = next_index

    return left_node, current_index

def _parse_term(tokens: List[tuple[str, str]], start_index: int) -> tuple[FormulaNode, int]:
    """Parses term: unary {(* | /) unary}"""
    left_node, current_index = _parse_unary(tokens, start_index)

    while current_index < len(tokens) and tokens[current_index][1] in ('*', '/'):
        op_token = tokens[current_index]
        op = op_token[1]
        current_index += 1

        right_node, next_index = _parse_unary(tokens, current_index)

        left_node = BinaryOp(left_node, op, right_node)
        current_index = next_index

    return left_node, current_index

def _parse_unary(tokens: List[tuple[str, str]], start_index: int) -> tuple[FormulaNode, int]:
    """Parses unary: (+ | -) unary | number | ref | ( expr )"""
    token = tokens[start_index]
    current_index = start_index + 1

    if token[1] in ('+', '-'):
        op = token[1]
        operand_node, next_index = _parse_unary(tokens, current_index)
        return UnaryOp(op, operand_node), next_index

    elif token[0] == 'NUMBER':
        value = float(token[1]) if '.' in token[1] else int(token[1])
        return NumberLiteral(value), start_index + 1

    elif token[0] == 'REFERENCE':
        return Reference(token[1].upper()), start_index + 1

    elif token[1] == '(':
        expr_node, next_index = _parse_expression(tokens, start_index + 1)

        if next_index >= len(tokens) or tokens[next_index][1] != ')':
            raise FormulaError("Unbalanced parentheses")

        return ParenthesizedExpression(expr_node), next_index + 1

    else:
        # Must be a starting expression element
        raise FormulaError(f"Expected number, reference, or '(', found {token[1]}")


def parse_formula(source: str) -> FormulaNode:
    """Parses the formula text (after '=')."""
    source = source.strip()
    if not source:
        raise FormulaError("Formula cannot be empty")

    tokens = _tokenize(source)

    if not tokens:
        raise FormulaError("Empty formula after tokenization")

    # Start parsing from the beginning
    tree, final_index = _parse_expression(tokens, 0)

    if final_index != len(tokens):
        raise FormulaError(f"Unconsumed tokens remaining: {tokens[final_index:]}")

    return tree

# --- Dependency Extraction ---

def references(tree: FormulaNode) -> Set[str]:
    """Returns the set of upper-case cell names referenced by the tree."""
    refs = set()

    if isinstance(tree, NumberLiteral):
        return refs

    elif isinstance(tree, Reference):
        return {tree.name}

    elif isinstance(tree, BinaryOp):
        refs.update(references(tree.left))
        refs.update(references(tree.right))
        return refs

    elif isinstance(tree, UnaryOp):
        refs.update(references(tree.operand))
        return refs

    elif isinstance(tree, ParenthesizedExpression):
        return references(tree.expr)

    return refs

# --- Evaluation Logic ---

def _resolve_value(node: FormulaNode, lookup: Callable[[str], Any]) -> Union[int, float, str, ErrorValue]:
    """
    Recursively evaluates a node's value based on the lookup table.
    Handles literals, references, and structure.
    """

    if isinstance(node, NumberLiteral):
        return node.value

    elif isinstance(node, Reference):
        name = node.name
        cell_value = lookup(name)

        if cell_value is None:
            # Empty cell returns 0 for arithmetic context
            return 0
        if isinstance(cell_value, str) and cell_value.startswith('#'):
            # Propagate errors/cycles
            return cell_value
        if isinstance(cell_value, str) and '=' in cell_value:
             # If it's a formula, it should have been evaluated, but if it's text, return it as is.
             # This path should ideally not be hit if dependency tracking is perfect.
             # Rule 2: If only a reference, return text unchanged.
             return cell_value
        return cell_value

    elif isinstance(node, BinaryOp):
        left_val = _resolve_value(node.left, lookup)
        right_val = _resolve_value(node.right, lookup)

        # Rule 3: Error propagation
        if isinstance(left_val, str) and left_val.startswith('#'):
            return left_val
        if isinstance(right_val, str) and right_val.startswith('#'):
            return right_val

        # Rule 3: Text propagation
        if isinstance(left_val, str) and not left_val.startswith('#'):
            return ERROR_GENERIC
        if isinstance(right_val, str) and not right_val.startswith('#'):
            return ERROR_GENERIC

        # Rule 4: Arithmetic
        try:
            if node.op == '+':
                return left_val + right_val
            elif node.op == '-':
                return left_val - right_val
            elif node.op == '*':
                return left_val * right_val
            elif node.op == '/':
                if right_val == 0:
                    return ERROR_GENERIC
                return left_val / right_val
        except TypeError:
            # Should be caught by string checks above, but good safeguard
            return ERROR_GENERIC

        return ERROR_GENERIC # Fallback

    elif isinstance(node, UnaryOp):
        operand_val = _resolve_value(node.operand, lookup)

        if isinstance(operand_val, str) and operand_val.startswith('#'):
            return operand_val

        if isinstance(operand_val, str) and not operand_val.startswith('#'):
            return ERROR_GENERIC

        # Rule 4 (Unary context):
        if node.op == '+':
            return operand_val + 0 if isinstance(operand_val, (int, float)) else operand_val
        elif node.op == '-':
            if isinstance(operand_val, (int, float)):
                return -operand_val
            # If it's text, unary negation is undefined/error, but following rule 3 logic:
            return ERROR_GENERIC

    elif isinstance(node, ParenthesizedExpression):
        return _resolve_value(node.expr, lookup)

    raise RuntimeError("Unhandled node type during evaluation.")


def evaluate(tree: FormulaNode, lookup: Callable[[str], Any]) -> Union[int, float, str, ErrorValue]:
    """Computes the formula's value given a lookup function."""

    # Special case: If the formula only references one cell and that cell holds text, 
    # the result must be that text (Rule 2).
    if isinstance(tree, Reference):
        return lookup(tree.name)

    # Check if the structure is purely a reference that was wrapped (e.g., =A1)
    # This check is complex because 'lookup' returns the raw cell value.
    # If the top level is NOT a reference, we proceed with full evaluation.

    result = _resolve_value(tree, lookup)

    # Final check for Rule 2: If the result is a non-error string, it must be text.
    # If the original formula was just "=A1" and A1="hi", _resolve_value returns "hi".
    # If the original formula was "=2+2", _resolve_value returns 4.
    # We must ensure that if the result is a string, it truly came from text storage,
    # not from an arithmetic operation that resulted in an unexpected string (which shouldn't happen).

    if isinstance(result, str) and not result.startswith('#'):
        # This path implies the formula resolved purely to text, which is only valid 
        # if the formula *was* a direct reference. Since we handled direct reference above,
        # if we reach here, it must be an error or a calculation. We return the result.
        return result

    return result

