```python
# sheet/graph.py
from typing import Set, Iterable

class DependencyGraph:
    """Tracks cell dependencies (precedents and dependents)."""

    def __init__(self):
        # Maps cell -> set of cells it depends on (precedents)
        self._precedents: dict[str, Set[str]] = {}
        # Maps cell -> set of cells that depend on it (dependents)
        self._dependents: dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Sets the set of cells that 'cell' depends on."""

        # 1. Update Precedents for 'cell'
        new_precedents = set(p for p in precedents if p)
        if cell not in self._precedents:
            self._precedents[cell] = set()

        self._precedents[cell] = new_precedents

        # 2. Update Dependents for all old/new precedents

        # Get old precedents for removal
        old_precedents = self._precedents.get(cell, set()).copy()

        # Clear old dependency links pointing to 'cell'
        for old_p in old_precedents:
            if old_p in self._dependents:
                self._dependents[old_p].discard(cell)

        # Add new dependency links pointing to 'cell'
        for new_p in new_precedents:
            if new_p not in self._dependents:
                self._dependents[new_p] = set()
            self._dependents[new_p].add(cell)

        # Ensure 'cell' exists in dependents map if it was previously isolated
        if cell not in self._dependents:
            self._dependents[cell] = set()


    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells that 'cell' depends on."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct cells that depend on 'cell'."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """Returns every cell that refers to 'cell', directly or indirectly.
           Includes 'cell' itself only if it's on a cycle."""

        # Use DFS/BFS starting from 'cell' following the 'dependents' edges
        queue = [cell]
        visited = {cell}

        while queue:
            current = queue.pop(0)

            # Check if this cell is part of a cycle involving itself (precedent check)
            # This check is more complex: we need to see if the path from a dependent back to 'cell' closes a loop.
            # For simplicity matching the requirement: "It contains cell itself only when cell is on a cycle."
            # We defer the full cycle check to cycle_cells(), but for reachability:

            for dependent in self.dependents.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    queue.append(dependent)

        # A simpler approach matching common dependency tree behavior: 
        # return all reachable nodes via the dependents graph.
        return visited

    def cycle_cells(self) -> Set[str]:
        """
        Identifies all cells lying on a circular reference path.
        Uses DFS with tracking of nodes currently in the recursion stack.
        """
        visiting = set()
        visited = set()
        cycles = set()

        def dfs(cell: str):
            if cell in visiting:
                cycles.add(cell)
                return True # Cycle detected starting/passing through here
            if cell in visited:
                return False # Already fully processed and known not to start a cycle here

            visiting.add(cell)

            # Follow precedents (backward dependency)
            for precedent in self.precedents.get(cell, set()):
                if dfs(precedent):
                    cycles.add(cell) # If precedent is in a cycle, this cell is too

            visiting.remove(cell)
            visited.add(cell)
            return cell in cycles

        # We must check every cell that has precedents, as a cycle might be isolated
        all_cells = set(self._precedents.keys()) | set(self._dependents.keys())

        for cell in all_cells:
            # Reset state if necessary, but DFS handles this internally if we rely on the return value
            if cell not in visited:
                dfs(cell)

        return cycles
