# sheet/sheet.py
from typing import Any, Dict, List, Callable, Optional, Tuple
from .formula import parse_formula, references, evaluate, FormulaError, ERROR_GENERIC, ERROR_CYCLE
from .graph import DependencyGraph

class Sheet:
    def __init__(self):
        # Storage: CellName (str) -> RawInput (str)
        self._raw_data: Dict[str, str] = {}
        # Calculated Values: CellName (str) -> Value (int, float, str, ErrorValue, None)
        self._values: Dict[str, Any] = {}

        # State Tracking
        self.evaluations: int = 0
        self._dependency_graph = DependencyGraph()

        # Pre-populate structure for easy access, though not strictly necessary for functionality
        # We rely on lazy creation/lookup for cells not yet set.

    # --- Utility Methods ---

    @staticmethod
    def _parse_number(s: str) -> Optional[Union[int, float]]:
        s = s.strip()
        if not s:
            return None
        if s.startswith('-'):
            s = s[1:]

        if '.' in s:
            try:
                return float(s)
            except ValueError:
                return None
        else:
            try:
                return int(s)
            except ValueError:
                return None

    @staticmethod
    def _cell_name_to_coords(name: str) -> Tuple[str, int]:
        """Converts 'A1' -> ('A', 1)"""
        if not name or not name[0].isalpha():
            raise ValueError(f"Invalid cell name format: {name}")

        col_str = ""
        row_str = ""

        for i, char in enumerate(name):
            if char.isalpha():
                col_str += char
            elif char.isdigit():
                row_str += char
            else:
                raise ValueError(f"Invalid character in cell name: {char}")

        if not col_str or not row_str:
            raise ValueError(f"Incomplete cell name: {name}")

        # Validation: Column A-Z (max 26 chars), Row 1-999
        if len(col_str) > 1 and col_str[0].isalpha() and col_str[1].isalpha():
             # More than one letter, e.g., AA1, ZZ1000
             pass # Allowed up to Z

        if not (1 <= int(row_str) <= 999):
            raise ValueError(f"Row number out of bounds (1-999): {name}")

        if len(row_str) > 1 and row_str.startswith('0'):
            raise ValueError(f"Row number cannot have leading zeros: {name}")

        return col_str, int(row_str)

    @classmethod
    def _validate_name(cls, name: str):
        """Validates cell name format and bounds."""
        name = name.upper()
        if not name or not name[0].isalpha():
            raise ValueError(f"Invalid cell name format: {name}")

        try:
            _, row = cls._cell_name_to_coords(name)
            # Check column limit A-Z (Max 26 chars)
            if len(name) - len(str(row)) > 26:
                 raise ValueError("Column name too long.")
        except ValueError as e:
            raise ValueError(f"Invalid cell name '{name}': {e}")

    @staticmethod
    def _get_row_major_order(names: Set[str]) -> List[str]:
        """Sorts cell names by row, then column."""
        def sort_key(name: str) -> Tuple[int, str]:
            try:
                _, row = Sheet._cell_name_to_coords(name)
                col = name[:len(name) - len(str(row))]
                return (row, col)
            except ValueError:
                # Should not happen if names are valid
                return (9999, "") 

        return sorted(list(names), key=sort_key)

    # --- Public Interface ---

    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores the cell's input and recalculates affected cells.
        Returns list of changed cell names in row-major order.
        """
        self._validate_name(name)
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        old_raw = self._raw_data.get(name, '')
        if raw == old_raw:
            return [] # No change

        # 1. Parse and store raw data
        self._raw_data[name] = raw

        # 2. Determine if it's a formula or literal/text
        is_formula = raw.strip().startswith('=')

        if is_formula:
            try:
                formula_source = raw.strip()[1:].strip()
                tree = parse_formula(raw)

                # 3. Dependency Tracking
                precedents = references(tree)
                self._dependency_graph.set_dependencies(name, precedents)

                # Mark for recalculation
                needs_recalc = True
            except FormulaError as e:
                # If parsing fails, the sheet state must be completely unchanged
                self._raw_data[name] = old_raw
                raise e
        else:
            # Literal or Text
            self._dependency_graph.set_dependencies(name, [])
            needs_recalc = True

        # 4. Identify cells that need evaluation (the affected set)
        affected_cells = set(self._dependency_graph.all_dependents(name))

        # 5. Recalculation Loop

        # Ensure we process in a safe order (Topological sort implied by calculation flow)
        # We must evaluate the set of affected_cells.

        cells_to_evaluate = self._get_row_major_order(affected_cells)

        # Recalculation must happen iteratively until stable or stuck in cycles
        # Since set() only returns things reachable, we rely on the calculation loop to handle cycles.

        # Initialize the change tracking set
        changed_names = set()

        # The recalculation must happen *after* all dependencies are up-to-date.
        # This means we need a propagation loop, not just one pass over affected_cells.

        # Simple iterative relaxation until no change occurs in a pass, or we hit a safety limit

        stable = False
        while not stable:
            stable = True
            current_pass_changes: List[str] = []

            # We only need to iterate over the cells that were affected by the initial change OR 
            # cells that were affected by changes in the current pass.

            cells_to_check_this_pass = self._get_row_major_order(affected_cells | changed_names)

            for cell_name in cells_to_check_this_pass:
                # If this cell was the original change, we skip it for evaluation in this loop, 
                # as its raw input is already set.
                if cell_name == name:
                    continue

                # If it's not in _values, it's currently None or uninitialized
                current_value = self._values.get(cell_name)
                old_value = current_value
                new_value = None

                # 1. Check for Cycles
                if cell_name in self._dependency_graph.cycle_cells():
                    new_value = ERROR_CYCLE
                else:
                    # 2. Evaluate Formula (if it has one)
                    raw_input = self._raw_data.get(cell_name, '')
                    if raw_input.strip().startswith('='):
                        try:
                            tree = parse_formula(raw_input)
                            # Lookup function provided to evaluator
                            def lookup(c: str) -> Any:
                                # Must return the *current* calculated value
                                return self._values.get(c, None) 

                            new_value = evaluate(tree, lookup)
                        except FormulaError:
                            # Should not happen if the sheet state was consistent, but handle defensively
                            new_value = ERROR_GENERIC
                    else:
                        # Literal or Text
                        new_value = self._parse_literal_or_text(raw_input)

                # 3. Check for change
                if old_value != new_value:
                    self._values[cell_name] = new_value

                    # If the value changed, mark as unstable for next pass
                    stable = False
                    current_pass_changes.append(cell_name)
                    changed_names.add(cell_name)

            # Update affected set for the next pass: add all newly changed cells
            if not stable:
                affected_cells.update(current_pass_changes)

        # 6. Update Evaluation Count and Return

        # Count only formulas that were successfully evaluated during the stable phase
        eval_count_increase = 0
        for cell_name in changed_names:
            raw_input = self._raw_data.get(cell_name, '')
            if raw_input.strip().startswith('='):
                # If the cell was evaluated (i.e., not a cycle and not the original setter)
                if cell_name not in self._dependency_graph.cycle_cells() and cell_name != name:
                    eval_count_increase += 1

        self.evaluations += eval_count_increase

        # The required return list must be the union of the initial affected set and all cells 
        # that actually changed during propagation, ordered row-major.
        final_changed = self._get_row_major_order(affected_cells | changed_names)

        return final_changed

    def _parse_literal_or_text(self, raw: str) -> Union[int, float, str, None]:
        """Parses raw input that is not a formula."""
        stripped = raw.strip()
        if not stripped:
            return None # Empty cell

        num = self._parse_number(stripped)
        if num is not None:
            return num

        # Everything else is text
        return raw # Store exactly as given

    def get(self, name: str) -> Any:
        """Returns the calculated value of the cell."""
        self._validate_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        """Returns the raw input stored for the cell."""
        self._validate_name(name)
        return self._raw_data.get(name, '')

    def cells(self) -> List[str]:
        """Returns non-empty cells in row-major order."""
        active_cells = set(self._raw_data.keys())
        # Filter out empty cells (raw == '')
        non_empty = {name for name in active_cells if self._raw_data[name].strip() != ''}
        return self._get_row_major_order(non_empty)

