```python
# sheet/formula.py
from typing import Any, Dict, List, Union, Set, Callable
import re

# --- Custom Types ---

class FormulaError(ValueError):
    """Raised when a formula cannot be parsed or evaluated."""
    pass

class ErrorValue(str):
    """Represents a calculated error state in a cell."""
    pass

ERROR_GENERIC = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- Formula Structure ---

class FormulaNode:
    pass

class NumberLiteral(FormulaNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class Reference(FormulaNode):
    def __init__(self, name: str):
        self.name = name

class BinaryOp(FormulaNode):
    def __init__(self, left: FormulaNode, op: str, right: FormulaNode):
        self.left = left
        self.op = op
        self.right = right

class UnaryOp(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op
        self.operand = operand

class ParenthesizedExpression(FormulaNode):
    def __init__(self, expr: FormulaNode):
        self.expr = expr

# --- Parsing Logic ---

def _validate_reference_name(name: str):
    """Validates if a reference name is within sheet bounds (A-Z, 1-999, no leading zero)."""
    if not name or not name[0].isalpha():
        raise FormulaError(f"Invalid reference name format: {name}")

    col_str = ""
    row_str = ""
    for char in name:
        if char.isalpha():
            col_str += char
        elif char.isdigit():
            row_str += char
        else:
            raise FormulaError(f"Invalid character in reference name: {char}")

    # Column check: A-Z (max 26 chars)
    if len(col_str) > 26:
        raise FormulaError("Reference name too long for columns.")

    if not row_str:
        raise FormulaError(f"Reference name missing row number: {name}")

    row_num = int(row_str)

    # Row checks: 1-999, no leading zero if > 1 digit
    if not (1 <= row_num <= 999):
        raise FormulaError(f"Row number out of bounds (1-999): {name}")

    if len(row_str) > 1 and row_str.startswith('0'):
        raise FormulaError(f"Row number cannot have leading zeros: {name}")

    # Check for single letter column limit (A-Z)
    if len(col_str) > 1 and len(col_str) > 26: # Redundant, but reinforces boundary check
        raise FormulaError("Column name exceeds Z.")


def _tokenize(source: str) -> List[tuple[str, str]]:
    """Splits the formula string into meaningful tokens."""
    token_specification = [
        ('NUMBER', r'\d+(\.\d*)?'),
        ('REFERENCE', r'[a-zA-Z]+\d+'),
        ('OP', r'[+\-*/()]'),
        ('SKIP', r'\s+'),
        ('MISMATCH', r'.'),
    ]
    tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_specification)

    tokens = []
    for mo in re.finditer(tok_regex, source):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Unexpected character: {value}")
        tokens.append((kind, value))
    return tokens

def _parse_expression(tokens: List[tuple[str, str]], start_index: int) -> tuple[FormulaNode, int]:
    """Parses expr: term {(+ | -) term}"""
    left_node, current_index = _parse_term(tokens, start_index)

    while current_index < len(tokens) and tokens[current_index][1] in ('+', '-'):
        op_token = tokens[current_index]
        op = op_token[1]
        current_index += 1

        right_node, next_index = _parse_term(tokens, current_index)

        left_node = BinaryOp(left_node, op, right_node)
        current_index = next_index

    return left_node, current_index

def _parse_term(tokens: List[tuple[str, str]], start_index: int) -> tuple[FormulaNode, int]:
    """Parses term: unary {(* | /) unary}"""
    left_node, current_index = _parse_unary(tokens, start_index)

    while current_index < len(tokens) and tokens[current_index][1] in ('*', '/'):
        op_token = tokens[current_index]
        op = op_token[1]
        current_index += 1

        right_node, next_index = _parse_unary(tokens, current_index)

        left_node = BinaryOp(left_node, op, right_node)
        current_index = next_index

    return left_node, current_index

def _parse_unary(tokens: List[tuple[str, str]], start_index: int) -> tuple[FormulaNode, int]:
    """Parses unary: (+ | -) unary | number | ref | ( expr )"""
    token = tokens[start_index]

    if token[1] in ('+', '-'):
        op = token[1]
        operand_node, next_index = _parse_unary(tokens, start_index + 1)
        return UnaryOp(op, operand_node), next_index

    elif token[0] == 'NUMBER':
        value = float(token[1]) if '.' in token[1] else int(token[1])
        return NumberLiteral(value), start_index + 1

    elif token[0] == 'REFERENCE':
        # Validate reference immediately upon parsing
        name = token[1].upper()
        _validate_reference_name(name)
        return Reference(name), start_index + 1

    elif token[1] == '(':
        expr_node, next_index = _parse_expression(tokens, start_index + 1)

        if next_index >= len(tokens) or tokens[next_index][1] != ')':
            raise FormulaError("Unbalanced parentheses")

        return ParenthesizedExpression(expr_node), next_index + 1

    else:
        raise FormulaError(f"Expected number, reference, or '(', found {token[1]}")


