    """Parses the formula text (after '=')."""
    source = source.strip()
    if not source:
        raise FormulaError("Formula cannot be empty")

    tokens = _tokenize(source)

    if not tokens:
        raise FormulaError("Empty formula after tokenization")

    tree, final_index = _parse_expression(tokens, 0)

    if final_index != len(tokens):
        raise FormulaError(f"Unconsumed tokens remaining: {tokens[final_index:]}")

    return tree

