class Sheet:
    def __init__(self):
        # Storage: CellName (str) -> RawInput (str)
        self._raw_data: Dict[str, str] = {}
        # Calculated Values: CellName (str) -> Value (int, float, str, ErrorValue, None)
        self._values: Dict[str, Any] = {}

        self.evaluations: int = 0
        self._dependency_graph = DependencyGraph()

    # --- Utility Methods ---

    @staticmethod
    def _parse_number(s: str) -> Optional[Union[int, float]]:
        s = s.strip()
        if not s:
            return None

        # Handle optional leading negative sign (only for literals, not formulas)
        sign = 1
        if s.startswith('-'):
            sign = -1
            s = s[1:]

        if '.' in s:
            try:
                return sign * float(s)
            except ValueError:
                return None
        else:
            try:
                return sign * int(s)
            except ValueError:
                return None

    @staticmethod
    def _cell_name_to_coords(name: str) -> Tuple[str, int]:
        """Converts 'A1' -> ('A', 1)"""
        if not name or not name[0].isalpha():
            raise ValueError(f"Invalid cell name format: {name}")

        col_str = ""
        row_str = ""

        for i, char in enumerate(name):
            if char.isalpha():
                col_str += char
            elif char.isdigit():
                row_str += char
            else:
                raise ValueError(f"Invalid character in cell name: {char}")

        if not col_str or not row_str:
            raise ValueError(f"Incomplete cell name: {name}")

        # Row validation (1-999, no leading zeros)
        if not (1 <= int(row_str) <= 999):
            raise ValueError(f"Row number out of bounds (1-999): {name}")

        if len(row_str) > 1 and row_str.startswith('0'):
            raise ValueError(f"Row number cannot have leading zeros: {name}")

        return col_str, int(row_str)

    @classmethod
    def _validate_name(cls, name: str):
        """Validates cell name format and bounds (A-Z, 1-999)."""
        name = name.upper()
        try:
            col, row = cls._cell_name_to_coords(name)
            # Column validation: A-Z (max 26 chars)
            if len(col) > 26:
                 raise ValueError("Column name too long.")
        except ValueError as e:
            raise ValueError(f"Invalid cell name '{name}': {e}")

    @staticmethod
    def _get_row_major_order(names: Set[str]) -> List[str]:
        """Sorts cell names by row, then column."""
        def sort_key(name: str) -> Tuple[int, str]:
            try:
                _, row = Sheet._cell_name_to_coords(name)
                # Column is everything before the row number string
                row_str_len = len(str(row))
                col = name[:-row_str_len]
                return (row, col)
            except ValueError:
                return (9999, "") 

        return sorted(list(names), key=sort_key)

    def _parse_literal_or_text(self, raw: str) -> Union[int, float, str, None]:
        """Parses raw input that is not a formula."""
        stripped = raw.strip()
        if not stripped:
            return None # Empty cell

        num = self._parse_number(stripped)
        if num is not None:
            return num

        # Everything else is text, store exactly as given
        return raw 

    # --- Public Interface ---

    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores the cell's input and recalculates affected cells.
        Returns list of changed cell names in row-major order.
        """
        self._validate_name(name)
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        old_raw = self._raw_data.get(name, '')
        if raw == old_raw:
            return [] 

        # 1. Parse and store raw data
        self._raw_data[name] = raw

        is_formula = raw.strip().startswith('=')

        if is_formula:
            try:
                formula_source = raw.strip()[1:].strip()
                tree = parse_formula(raw)

                # 2. Dependency Tracking
                precedents = references(tree)
                self._dependency_graph.set_dependencies(name, precedents)
                needs_recalc = True
            except FormulaError as e:
                # If parsing fails, revert storage and re-raise
                self._raw_data[name] = old_raw
                raise e
        else:
            # Literal or Text
            self._dependency_graph.set_dependencies(name, [])
            needs_recalc = True

        # 3. Identify cells that need evaluation (the affected set)
        affected_cells = self._dependency_graph.all_dependents(name)

        changed_names: Set[str] = set()

        # --- Recalculation Loop (Iterative Stability) ---

        stable = False
        while not stable:
            stable = True

            # Collect all cells that need to be checked this pass: 
            # Affected set + those that changed last pass
            cells_to_check = affected_cells | changed_names

            # Store the state before this pass to detect changes
            old_values_snapshot = {c: self._values.get(c) for c in cells_to_check}

            for cell_name in self._get_row_major_order(cells_to_check):

                old_value = old_values_snapshot.get(cell_name)
                new_value = None

                # Rule 2: Cycle check
                if cell_name in self._dependency_graph.cycle_cells():
                    new_value = ERROR_CYCLE
                else:
                    raw_input = self._raw_data.get(cell_name, '')

                    if raw_input.strip().startswith('='):
                        # Formula evaluation
                        try:
                            tree = parse_formula(raw_input)

                            # Lookup function must return the *currently stable* value
                            def lookup(c: str) -> Any:
                                return self._values.get(c) 

                            new_value = evaluate(tree, lookup)

                        except FormulaError:
                            new_value = ERROR_GENERIC
                    else:
                        # Literal or Text
                        new_value = self._parse_literal_or_text(raw_input)

                # Check for actual value change
                if old_value != new_value:
                    self._values[cell_name] = new_value

                    # Mark change, which necessitates another pass
                    stable = False
                    changed_names.add(cell_name)

        # 4. Update Evaluation Count (Count unique, successful formula evaluations)

        for cell_name in changed_names:
            raw_input = self._raw_data.get(cell_name, '')
            if raw_input.strip().startswith('='):
                # Only count if it was evaluated (not a cycle) and it wasn't the original setter 
                # (The original setter's raw input change triggered the cascade, it wasn't "evaluated" in the loop)
                if cell_name not in self._dependency_graph.cycle_cells() and cell_name != name:
                    self.evaluations += 1

        # 5. Return result
        # The result must include the original cell plus all cells that changed during propagation
        return self._get_row_major_order(affected_cells | changed_names)

    def get(self, name: str) -> Any:
        """Returns the calculated value of the cell."""
        self._validate_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        """Returns the raw input stored for the cell."""
        self._validate_name(name)
        return self._raw_data.get(name, '')

    def cells(self) -> List[str]:
        """Returns non-empty cells in row-major order."""
        active_cells = set(self._raw_data.keys())
        # Filter out empty cells (raw == '')
        non_empty = {name for name in active_cells if self._raw_data[name].strip() != ''}
        return self._get_row_major_order(non_empty)
