class PackageIndex:
    """Stores known package versions and their requirements."""

    def __init__(self):
        # {name: {version_str: {dep_name: range_spec}, ...}, ...}
        self._index: Dict[str, Dict[str, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a release version to the index."""
        try:
            v = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Cannot add {name} version {version_str}: {e}")

        if name not in self._index:
            self._index[name] = {}

        if version_str in self._index[name]:
            raise ValueError(f"Version {version_str} of package {name} already exists.")

        if requires:
            parsed_requires = {}
            for dep_name, spec in requires.items():
                try:
                    parsed_requires[dep_name] = Range(spec)
                except ValueError as e:
                    raise ValueError(f"Invalid dependency specification for {name}@{version_str}: {e}")
            self._index[name][version_str] = parsed_requires
        else:
            self._index[name][version_str] = {}

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a structured dictionary."""
        index = cls()
        for name, versions_data in data.items():
            if name not in index._index:
                index._index[name] = {}
            for version_str, requirements in versions_data.items():
                # Convert string specs to Range objects during loading
                parsed_requires = {}
                for dep_name, spec in requirements.items():
                    try:
                        parsed_requires[dep_name] = Range(spec)
                    except ValueError as e:
                        raise ValueError(f"Error loading specification for {name}@{version_str}: {e}")
                index._index[name][version_str] = parsed_requires
        return index

    def versions(self, name: str) -> List[Version]:
        """Returns the list of known Version objects for name, newest first."""
        if name not in self._index:
            return []

        versions = []
        for v_str in self._index[name].keys():
            versions.append(Version(v_str))

        # Sort newest first (descending)
        return sorted(versions, reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns the requirements for a specific version."""
        if name not in self._index or str(version) not in self._index[name]:
            raise KeyError(f"No release of {name} version {version} found in index.")

        # We return the Range objects directly
        return self._index[name][str(version)]
