        constraints = get_constraints(pkg_name, current_selection)

        # Get candidates (newest first)
        candidates = index.versions(pkg_name)

        if not candidates:
            # Failure: No versions exist for this package
            error_lines = [
                f"cannot resolve {pkg_name}"
            ]
            for _, range_obj in constraints:
                error_lines.append(f"  <root> requires {pkg_name} {range_obj}") # Defaulting requirer if not root
            # Note: We cannot know the exact requirer here easily, so we stick to the general format.
            # For the initial error, we rely on the caller to provide the specific context if necessary,
            # but here we generate the most likely explanation structure.
            return None # Signal failure to the caller


        # Iterate through candidates (newest first)
        for candidate_version in candidates:

            # 1. Check acceptability
            # We need a specialized check that returns the specific conflict reason if it fails.

            is_acceptable = True

            # Check 1: Constraints
            for requirer_str, range_obj in constraints:
                if not range_obj.contains(candidate_version):
                    # Conflict found based on range constraint
                    # Construct error explanation piece for this specific failure
                    error_lines = [f"cannot resolve {pkg_name}"]
                    for r_str, r_obj in constraints:
                        if r_str == requirer_str and not r_obj.contains(candidate_version):
                             error_lines.append(f"  {r_str} requires {pkg_name} {r_obj}")

                    # This is the first point of failure we report
                    return _format_and_raise_error(pkg_name, constraints, candidates, candidate_version, error_lines)


            # Check 2: Dependency Conflicts (Must be checked in alphabetical order of dependencies)
            try:
                candidate_reqs = index.requirements(pkg_name, candidate_version)
            except KeyError:
                continue # Should not happen

            conflicts = False
            for dep_name in sorted(candidate_reqs.keys()):
                if dep_name in current_selection:
                    selected_version = current_selection[dep_name]
                    range_obj = candidate_reqs[dep_name]

                    if not range_obj.contains(selected_version):
                        # Conflict found based on selected dependency

                        # Construct error explanation piece
                        error_lines = [f"cannot resolve {pkg_name}"]
                        for r_str, r_obj in constraints:
                             error_lines.append(f"  {r_str} requires {pkg_name} {r_obj}")

                        error_lines.append(
                             f"  {pkg_name} {candidate_version} requires {dep_name} {range_obj}, "
                             f"but {dep_name} {selected_version} is selected"
                        )
                        return _format_and_raise_error(pkg_name, constraints, candidates, candidate_version, error_lines)

            # If we reach here, the candidate is acceptable for the current state.

            # 2. Recurse (Select and expand order)

            new_selection = current_selection.copy()
            new_selection[pkg_name] = candidate_version

            new_order = current_order[:]

            # Identify new dependencies introduced by this candidate
            new_deps = set()
            try:
                candidate_reqs = index.requirements(pkg_name, candidate_version)
                for dep_name in candidate_reqs.keys():
                    if dep_name not in current_selection and dep_name not in new_order:
                        new_deps.add(dep_name)
            except KeyError:
                pass # No dependencies found, proceed.

            # Append new dependencies alphabetically to the order
            sorted_new_deps = sorted(list(new_deps))
            new_order.extend(sorted_new_deps)

            # 3. Recursive Call
            result = backtrack(new_order, new_selection)

            if result is not None:
                # Success down this path
                return result

            # 4. Failure: Undo (Backtrack happens implicitly by loop continuing)
            # If result was None, we try the next candidate version.

        # Exhausted all candidates for this package, fail this branch
        return None


    def _format_and_raise_error(self, pkg_name: str, constraints: List[Tuple[str, Range]], candidates: List[Version], failed_candidate: Version, error_lines: List[str]):
        """Helper to format the error and raise ResolutionError."""

        # Final check: If we failed because of version exclusion (no acceptable candidate),
        # we need to list all excluded versions if the reason wasn't dependency conflict.
        if not any("requires" in line for line in error_lines):
             # If the failure was simply that no candidate passed constraint checks:

            # Re-run check to find which versions failed the initial constraints
            unacceptable_versions_by_constraint = []

            for candidate in candidates:
                passes_all = True
                for _, range_obj in constraints:
                    if not range_obj.contains(candidate):
                        passes_all = False
                        break

                if not passes_all:
                    unacceptable_versions_by_constraint.append(candidate)

            # If the error was due to exclusion by constraints (not dependency conflict)
            if unacceptable_versions_by_constraint:
                 error_lines = [f"cannot resolve {pkg_name}"]
                 for _, range_obj in constraints:
                    # Since we are reporting the first failure, we report constraints first
                    error_lines.append(f"  <root> requires {pkg_name} {range_obj}")

                 for candidate in candidates:
                     if candidate in unacceptable_versions_by_constraint:
                         error_lines.append(f"  {pkg_name} {candidate} is excluded by the constraints")

            else:
                # This should be unreachable if the logic is perfectly followed, 
                # but if we failed without specific reasons, we fall back.
                error_lines = [f"cannot resolve {pkg_name} (Unspecified conflict)"]
                for _, range_obj in constraints:
                    error_lines.append(f"  <root> requires {pkg_name} {range_obj}")

        return ResolutionError(pkg_name, "\n".join(error_lines))


    # --- Initial Execution ---

    # Initial state setup
    initial_order = sorted(requirements.keys())

    try:
        final_selection = backtrack(initial_order, {})
    except ResolutionError as e:
        # Re-raise the structured error caught during recursion
        raise e
    except Exception as e:
        # Catch unexpected errors during the process
        raise ResolutionError("Unknown", f"An internal error occurred during resolution: {e}")


    if final_selection is None:
        # If backtrack returns None without raising ResolutionError (shouldn't happen 
        # if _format_and_raise_error is correctly integrated), we need a final catch.
        # For safety, we assume if None is returned, the last package processed failed.
        raise ResolutionError("Solver", "Resolution failed, but no specific conflict was recorded.")

    return final_selection
