import re
from functools import total_ordering

@total_ordering
class Version:
    """Represents a semantic version MAJOR.MINOR.PATCH."""
    def __init__(self, text: str):
        match = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", text)
        if not match:
            raise ValueError(f"Invalid version format: {text}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))

        self.major = major
        self.minor = minor
        self.patch = patch

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and \
               self.minor == other.minor and \
               self.patch == other.patch

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def to_tuple(self):
        return (self.major, self.minor, self.patch)

class Range:
    """Represents a version range constraint."""

    # Regex to capture operator and version string for constraints
    CONSTRAINT_PATTERN = re.compile(r"([=!<>~^]{1,2})?(\d+\.\d+\.\d+)")

    def __init__(self, spec: str):
        self._spec = spec.strip()
        self.constraints: List[Tuple[str, object]] = [] # Stores (op, bound_version_or_None)
        self._parse_spec()

    def _parse_spec(self):
        if not self._spec:
            raise ValueError("Empty range specification")

        parts = [p.strip() for p in self._spec.split(',')]

        for part in parts:
            if not part: continue

            # Check for wildcard first
            if part == "*":
                self.constraints.append(("wildcard", None))
                continue

            match = self.CONSTRAINT_PATTERN.match(part)

            if not match:
                raise ValueError(f"Unknown constraint format: {part}")

            op_raw, version_str = match.groups()

            if op_raw is None:
                # No explicit operator, assume equality
                op = "=="
                version_str = version_str
            else:
                op = op_raw
                version_str = version_str

            try:
                version = Version(version_str)
            except ValueError:
                raise ValueError(f"Bad version in range: {version_str}")

            # Standardize operators and apply special logic
            if op == "~":
                self._parse_tilde(version, part)
            elif op == "^":
                self._parse_caret(version, part)
            elif op == "==":
                self.constraints.append(("==", version))
            elif op == "!=":
                self.constraints.append(("!=", version))
            elif op == ">=":
                self.constraints.append((">=", version))
            elif op == ">":
                self.constraints.append((">=", version)) # Per common practice, treating > as >= if we don't support strict >
            elif op == "<=":
                self.constraints.append(("<=", version))
            elif op == "<":
                self.constraints.append(("<=", version)) # Per common practice, treating < as <= if we don't support strict <
            else:
                raise ValueError(f"Unknown operator: {op}")

    def _parse_caret(self, v: Version, part: str):
        """Handles ^X.Y.Z: >=X.Y.Z, <NextMajorOrMinor"""
        major, minor, patch = v.to_tuple()
        if major == 0 and minor == 0 and patch == 0:
            # ^0.0.0 is >=0.0.0, <0.0.1
            upper_bound = Version(f"0.0.{patch + 1}")
        elif major == 0:
            # ^0.Y.Z is >=0.Y.Z, <0.(Y+1).0
            upper_bound = Version(f"0.{minor + 1}.0")
        else:
            # ^X.Y.Z is >=X.Y.Z, <(X+1).0.0
            upper_bound = Version(f"{major + 1}.0.0")

        self.constraints.append((">=", v))
        self.constraints.append(("<", upper_bound))

    def _parse_tilde(self, v: Version, part: str):
        """Handles ~X.Y.Z: >=X.Y.Z, <X.(Y+1).0 (if Z > 0) or <X.Y.(Z+1) (if Z = 0)"""
        major, minor, patch = v.to_tuple()

        if patch > 0:
            # ~1.2.3 is >=1.2.3, <1.3.0
            upper_bound = Version(f"{major}.{minor + 1}.0")
        else:
            # ~1.2.0 is >=1.2.0, <1.2.1
            upper_bound = Version(f"{major}.{minor}.{patch + 1}")

        self.constraints.append((">=", v))
        self.constraints.append(("<", upper_bound))


    def contains(self, v: Version) -> bool:
        """Checks if the version v satisfies all constraints."""
        for op, bound in self.constraints:
            if op == "wildcard":
                continue

            # Comparison logic
            v_val = v.to_tuple()
            b_val = bound.to_tuple()

            if op == "==" and v_val != b_val:
                return False
            elif op == "!=" and v_val == b_val:
                return False
            # NOTE: We use standard comparison logic derived from Python's tuple comparison
            elif op == ">=" and v_val < b_val:
                return False
            elif op == "<=" and v_val > b_val:
                return False
            elif op == ">" and v_val <= b_val: # Strict >
                return False
            elif op == "<" and v_val >= b_val: # Strict <
                return False
        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __str__(self):
        # Reconstruct the original spec, but removing whitespace
        return "".join(c.strip() for c in self._spec.split(','))

    def __repr__(self):
        return f"Range('{self._spec}')"
