from typing import Dict, List, Tuple, Optional
from resolve.index import PackageIndex
from resolve.versions import Version, Range

class ResolutionError(Exception):
    """Raised when dependency resolution fails."""
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(self.explanation)

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
    """
    Resolves dependencies based on root requirements using depth-first backtracking.
    """

    root_requirements_parsed: Dict[str, Range] = {}
    for name, spec in requirements.items():
        try:
            root_requirements_parsed[name] = Range(spec)
        except ValueError as e:
            raise ValueError(f"Root requirement '{name} {spec}' is invalid: {e}")

    # Order: List of package names to process (alphabetical root order + newly introduced deps)
    initial_order = sorted(requirements.keys())

    def get_constraints(pkg_name: str, current_selection: Dict[str, Version]) -> List[Tuple[str, Range]]:
        """
        Gathers all constraints applicable to pkg_name in selection order.
        (requirer_str, range_obj)
        """
        constraints: List[Tuple[str, Range]] = []

        # 1. Root requirements constraint
        if pkg_name in root_requirements_parsed:
            constraints.append(("<root>", root_requirements_parsed[pkg_name]))

        # 2. Selected packages' requirements
        for selected_name, selected_version in current_selection.items():
            if selected_name == pkg_name:
                continue

            try:
                reqs = index.requirements(selected_name, selected_version)
                if pkg_name in reqs:
                    range_obj = reqs[pkg_name]
                    requirer_str = f"{selected_name} {selected_version}"
                    constraints.append((requirer_str, range_obj))
            except KeyError:
                pass
        return constraints

    def _format_and_raise_error(pkg_name: str, constraints: List[Tuple[str, Range]], candidates: List[Version], failed_candidate: Optional[Version] = None) -> None:
        """
        Formats and raises ResolutionError based on the failure type.
        """
        error_lines = [f"cannot resolve {pkg_name}"]

        if failed_candidate:
            # Failure due to specific candidate not being acceptable (dependency conflict or constraint violation)

            # Check constraints first (This is the primary check for failure when candidates exist)
            constraint_fail = False
            for requirer_str, range_obj in constraints:
                if not range_obj.contains(failed_candidate):
                    error_lines.append(f"  {requirer_str} requires {pkg_name} {range_obj}")
                    constraint_fail = True
                    break

            if constraint_fail:
                 # If it failed constraints, we list constraints and then state the exclusion
                 for _, range_obj in constraints:
                     # Only list unique constraint lines once for clean output
                    error_lines.append(f"  <root> requires {pkg_name} {range_obj}")

                 # Re-run loop to find the actual specific constraint failure if the above logic was too simplistic
                 # Due to complexity, we simplify: if failed_candidate is provided, we assume the reason was found 
                 # and construct the most detailed error possible based on the failure type encountered in backtrack.

                 # If we are here, it means the specific failure was caught inside backtrack and passed the candidate.
                 # For simplicity matching the prompt's example structure, we list all constraints first.
                 error_lines = [f"cannot resolve {pkg_name}"]
                 for requirer_str, range_obj in constraints:
                     error_lines.append(f"  {requirer_str} requires {pkg_name} {range_obj}")
                 error_lines.append(f"  {pkg_name} {failed_candidate} is excluded by the constraints")

            else:
                # Failure due to dependency conflict (This case requires more context than available here, 
                # so we mimic the structure of the example provided in the prompt when a dependency is the issue)
                error_lines = [f"cannot resolve {pkg_name}"]
                for requirer_str, range_obj in constraints:
                     error_lines.append(f"  {requirer_str} requires {pkg_name} {range_obj}")
                # The exact dependency conflict line is constructed in backtrack before calling this helper.
                # Since we are calling this helper *after* determining the conflict in backtrack, we rely on the caller
                # to format the final dependency conflict line if that's the cause.
                # We rely on the caller passing sufficient info, or we assume the simplest failure state.
                error_lines.append(f"  {pkg_name} {failed_candidate} requires dependency constraint failure.") # Placeholder for complexity


        else:
            # Failure: No versions exist for this package
            error_lines.append("  no versions of {}".format(pkg_name))


        raise ResolutionError(pkg_name, "\n".join(error_lines))

    def backtrack(
        current_order: List[str], 
        current_selection: Dict[str, Version]
    ) -> Optional[Dict[str, Version]]:
        """
        The recursive backtracking search function.
        Returns the final selection if successful, otherwise None (triggering failure).
        """

        next_pkg_name = None
        for name in current_order:
            if name not in current_selection:
                next_pkg_name = name
                break

        if next_pkg_name is None:
            return current_selection.copy()

        pkg_name = next_pkg_name

        constraints = get_constraints(pkg_name, current_selection)
        candidates = index.versions(pkg_name)

        if not candidates:
            _format_and_raise_error(pkg_name, constraints, candidates)

        for candidate_version in candidates:

            # --- 1. Check Acceptability ---

            # Check 1: Range Constraints
            constraint_failed = False
            for requirer_str, range_obj in constraints:
                if not range_obj.contains(candidate_version):
                    # Failure due to constraint violation

                    # Build specific error explanation matching requirement
                    error_lines = [f"cannot resolve {pkg_name}"]
                    for r_str, r_obj in constraints:
                         if r_str == requirer_str and not r_obj.contains(candidate_version):
                             error_lines.append(f"  {r_str} requires {pkg_name} {r_obj}")

                    # Add exclusion line for the failing candidate
                    error_lines.append(f"  {pkg_name} {candidate_version} is excluded by the constraints")

                    raise ResolutionError(pkg_name, "\n".join(error_lines))

            # Check 2: Dependency Conflicts (Must be checked in alphabetical order of dependencies)
            try:
                candidate_reqs = index.requirements(pkg_name, candidate_version)
            except KeyError:
                continue # Should not happen

            dependency_conflict_found = False
            for dep_name in sorted(candidate_reqs.keys()):
                if dep_name in current_selection:
                    selected_version = current_selection[dep_name]
                    range_obj = candidate_reqs[dep_name]

                    if not range_obj.contains(selected_version):
                        dependency_conflict_found = True

                        # Build specific error explanation matching requirement
                        error_lines = [f"cannot resolve {pkg_name}"]
                        for r_str, r_obj in constraints:
                             error_lines.append(f"  {r_str} requires {pkg_name} {r_obj}")

                        # The specific conflict line
                        error_lines.append(
                            f"  {pkg_name} {candidate_version} requires {dep_name} {range_obj}, "
                            f"but {dep_name} {selected_version} is selected"
                        )
                        raise ResolutionError(pkg_name, "\n".join(error_lines))

            # --- 2. Recurse (Select and expand order) ---

            new_selection = current_selection.copy()
            new_selection[pkg_name] = candidate_version

            new_order = current_order[:]

            # Identify new dependencies introduced by this candidate
            new_deps = set()
            try:
                candidate_reqs = index.requirements(pkg_name, candidate_version)
                for dep_name in candidate_reqs.keys():
                    if dep_name not in current_selection and dep_name not in new_order:
                        new_deps.add(dep_name)
            except KeyError:
                pass 

            sorted_new_deps = sorted(list(new_deps))
            new_order.extend(sorted_new_deps)

            # Recursive Call
            result = backtrack(new_order, new_selection)

            if result is not None:
                return result

        # Exhausted all candidates for this package, fail this branch
        return None


    # --- Initial Execution ---

    try:
        return backtrack(initial_order, {})
    except ResolutionError as e:
        raise e
    except Exception as e:
        raise ResolutionError("Unknown", f"An internal error occurred during resolution: {e}")
