        next_pkg_name = current_order[0]

        if next_pkg_name in selected:
            # Already selected (shouldn't happen if order management is perfect, but safeguards against loops/duplicates)
            return search(current_order[1:], selected, constraint_history)

        # 1. Gather all constraints for next_pkg_name
        constraints: List[Tuple[str, Range, str]] = []

