            except ValueError:
                # This should ideally be caught before calling resolve, but we handle defensively.
                raise ResolutionError(next_pkg_name, f"Invalid root requirement specification for {next_pkg_name}: {root_spec}")


        # Constraints 2+: Requirements from already selected packages
        for i in range(len(constraint_history)):
            requirer_name, _, _ = constraint_history[i][0]
            if requirer_name != "<root>":
                requirer_version = selected[requirer_name]

                # Check if this selected package depends on next_pkg_name
                if next_pkg_name in index._index.get(requirer_name, {}).get(str(requirer_version), {}):
                    # Need to reconstruct the required Range from the index data for the specific version
                    required_deps = index.requirements(requirer_name, requirer_version)
                    if next_pkg_name in required_deps:
                        dep_range = required_deps[next_pkg_name]
                        # Requirer: name version
                        constraints.append((f"{requirer_name} {str(requirer_version)}", dep_range, f"{requirer_name} {str(requirer_version)}"))

        # 2. Identify candidates (Newest first)
        candidates_versions = index.versions(next_pkg_name)

        successful_candidates: List[Version] = []

        for candidate_version in candidates_versions:

            # Check Constraint 1: Does the version satisfy all gathered constraints?
            is_acceptable = True

            # Check internal constraints (must hold for this specific version)
            for _, required_range, _ in constraints:
                if not required_range.contains(candidate_version):
                    is_acceptable = False
                    break

            if not is_acceptable:
                # Mark this candidate as rejected due to constraints
                pass
            else:
                # Check Constraint 2: For every dependency of this candidate, 
                # if it's already selected, is the selected version in the candidate's range?

                candidate_deps = index.requirements(next_pkg_name, candidate_version)

                is_dependency_ok = True

                # Iterate through candidate's dependencies, sorted alphabetically by dependency name
                sorted_deps = sorted(candidate_deps.keys())

                for dep_name in sorted_deps:
                    if dep_name in selected:
                        selected_version = selected[dep_name]
                        required_range = candidate_deps[dep_name]

                        if not required_range.contains(selected_version):
                            is_dependency_ok = False
                            break

                if is_dependency_ok:
                    successful_candidates.append(candidate_version)

        # 3. Backtracking Search Loop

        if not successful_candidates:
            # Failure at this node. Construct error message.

            error_lines = [f"cannot resolve {next_pkg_name}"]

            # Constraint explanations
            for requirer, req_range, req_str in constraints:
                # Check if this specific constraint failed for *any* candidate, 
                # or if it's a structural failure (no versions known).

                if not index.versions(next_pkg_name):
                    # This handles the "no versions known" case if we reached this point without candidates
                    continue 

                # Check if the constraint failed for *all* candidates.
                # Since successful_candidates is empty, we check if *any* candidate fails it.

                # For the error message, we need to show the constraint applied.
                # We display the constraint regardless of whether it caused the failure, 
                # as the prompt suggests showing all constraints applied.
                error_lines.append(f"  {req_str} requires {next_pkg_name} {str(req_range)}")

            # Version exclusion explanations
            if not candidates_versions:
                error_lines.append(f"  no versions of {next_pkg_name} are known")
            else:
                # Iterate candidates newest first to match requirement
                for candidate_version in candidates_versions:

                    # Check if version is excluded by constraints
                    excluded_by_constraint = False
                    for _, required_range, _ in constraints:
                        if not required_range.contains(candidate_version):
                            error_lines.append(f"  {next_pkg_name} {str(candidate_version)} is excluded by the constraints")
                            excluded_by_constraint = True
                            break

                    if excluded_by_constraint:
                        continue

                    # If not excluded by constraint, check dependency conflicts
                    candidate_deps = index.requirements(next_pkg_name, candidate_version)
                    is_conflict = False

                    sorted_deps = sorted(candidate_deps.keys())
                    for dep_name in sorted_deps:
                        if dep_name in selected:
                            selected_version = selected[dep_name]
                            required_range = candidate_deps[dep_name]

                            if not required_range.contains(selected_version):
                                error_lines.append(f"  {next_pkg_name} {str(candidate_version)} requires {dep_name} {str(required_range)}, but {dep_name} {str(selected_version)} is selected")
                                is_conflict = True
                                break

                    # If a version was acceptable but didn't lead to success (this happens if recursion fails later), 
                    # it isn't explicitly listed in the error message structure provided, 
                    # as the error should point to the *first* step that found no acceptable candidate.
                    # If we reached here and successful_candidates was empty, it means all candidates failed one of the above checks.

            error_msg = "\n".join(error_lines)
            raise ResolutionError(next_pkg_name, error_msg)

        # Recursive Step: Try each acceptable candidate
        for candidate_version in successful_candidates:

            new_selected = selected.copy()
            new_selected[next_pkg_name] = candidate_version

            # Determine new packages to add to the order
            candidate_deps = index.requirements(next_pkg_name, candidate_version)
            newly_added_names = []
            for dep_name in sorted(candidate_deps.keys()):
                if dep_name not in new_selected:
                    newly_added_names.append(dep_name)

            # Append new names alphabetically to the end of the current order
            new_order = current_order[1:] + newly_added_names

            # Update history: The current selection is recorded for future checks
            new_history = constraint_history + [(next_pkg_name, [], f"{next_pkg_name} {str(candidate_version)}")]

            # Recurse
            result = search(new_order, new_selected, new_history)
            if result is not None:
                return result # Success path found

        # If we looped through all successful candidates and none succeeded:
        # This step fails. Construct and raise the error based on the failure at next_pkg_name.

        error_lines = [f"cannot resolve {next_pkg_name}"]

        # Constraint explanations
        for requirer, req_range, req_str in constraints:
             error_lines.append(f"  {req_str} requires {next_pkg_name} {str(req_range)}")

        # Version exclusion explanations
        if not candidates_versions:
            error_lines.append(f"  no versions of {next_pkg_name} are known")
        else:
            for candidate_version in candidates_versions:

                excluded_by_constraint = False
                for _, required_range, _ in constraints:
                    if not required_range.contains(candidate_version):
                        error_lines.append(f"  {next_pkg_name} {str(candidate_version)} is excluded by the constraints")
                        excluded_by_constraint = True
                        break

                if excluded_by_constraint:
                    continue

                candidate_deps = index.requirements(next_pkg_name, candidate_version)
                is_conflict = False

                sorted_deps = sorted(candidate_deps.keys())
                for dep_name in sorted_deps:
                    if dep_name in selected:
                        selected_version = selected[dep_name]
                        required_range = candidate_deps[dep_name]

                        if not required_range.contains(selected_version):
                            error_lines.append(f"  {next_pkg_name} {str(candidate_version)} requires {dep_name} {str(required_range)}, but {dep_name} {str(selected_version)} is selected")
                            is_conflict = True
                            break

                # If a candidate was acceptable by constraints but caused a failure downstream, 
                # we only list it if it conflicts with an already selected dependency.
                # If it passed all checks but recursion failed, we don't list it here per spec logic.

        error_msg = "\n".join(error_lines)
        raise ResolutionError(next_pkg_name, error_msg)


