# resolve/index.py
from typing import Dict, List, Optional
from .versions import Version, Range

class PackageIndex:
    """Stores known package releases and their dependencies."""

    def __init__(self):
        # Structure: {name: {version_str: {dep_name: Range, ...}}}
        self._index: Dict[str, Dict[str, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a release to the index."""
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Cannot add package: {e}")

        if name not in self._index:
            self._index[name] = {}

        if version_str in self._index[name]:
            raise ValueError(f"Duplicate release found for {name} version {version_str}")

        if requires:
            dependency_ranges = {}
            for dep_name, spec in requires.items():
                try:
                    dependency_ranges[dep_name] = Range(spec)
                except ValueError as e:
                    raise ValueError(f"Invalid dependency spec for {name}@{version_str}@{dep_name}: {e}")
        else:
            dependency_ranges = {}

        self._index[name][version_str] = dependency_ranges

    def versions(self, name: str) -> List[Version]:
        """Returns the list of known Versions of name, newest first."""
        if name not in self._index:
            return []

        version_objects = []
        for v_str in self._index[name].keys():
            try:
                version_objects.append(Version(v_str))
            except ValueError:
                pass

        # Sort descending (newest first)
        version_objects.sort(reverse=True)
        return version_objects

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns the dependency ranges for a specific released version."""
        if name not in self._index:
            raise KeyError(f"Package {name} not found in index.")

        version_str = str(version)
        if version_str not in self._index[name]:
            raise KeyError(f"Version {version_str} of {name} not found in index.")

        return self._index[name][version_str]

    @classmethod
    def from_dict(cls, data: Dict) -> 'PackageIndex':
        """Builds an index from a standardized dictionary structure."""
        index = cls()
        for name, version_data in data.items():
            if not isinstance(version_data, dict):
                raise ValueError(f"Malformed data for package {name}: version_data must be a dictionary.")

            for v_str, dep_data in version_data.items():
                if not isinstance(dep_data, dict):
                    raise ValueError(f"Malformed data for {name}@{v_str}: dependency data must be a dictionary.")

                # Convert string specs to Range objects
                requires_parsed = {}
                for dep_name, spec in dep_data.items():
                    try:
                        requires_parsed[dep_name] = Range(spec)
                    except ValueError as e:
                        raise ValueError(f"Failed to parse dependency spec for {name}@{v_str}@{dep_name}: {e}")

                index.add(name, v_str, requires=requires_parsed)
        return index
