# resolve/solver.py
from typing import Dict, List, Tuple, Optional, Union
from .versions import Version, Range
from .index import PackageIndex

class ResolutionError(Exception):
    """Raised when the package resolution fails."""
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(self.explanation)

    def __str__(self):
        return self.explanation

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
    """
    Resolves the package dependencies starting from the root requirements.
    """

    # Initial setup: Order is root requirement names sorted alphabetically.
    initial_order = sorted(requirements.keys())

    # State during search:
    # - order: List of package names to process, in selection order.
    # - selected: Dictionary {name: Version} of packages successfully selected.
    # - selected_by: Dictionary {name: List[Tuple[requirer_str, Version]]} tracking how each package was selected.

    def search(
        current_order: List[str], 
        selected: Dict[str, Version], 
        selected_by: Dict[str, List[Tuple[str, Version]]]
    ) -> Optional[Dict[str, Version]]:

        if not current_order:
            # Success: all required packages have been selected
            return selected

        # Find the next package to resolve (must be the first in the order that is not selected)
        next_pkg_name = current_order[0]

        # Skip if already selected (this handles cases where dependencies added to order were already resolved via another path)
        if next_pkg_name in selected:
            return search(current_order[1:], selected, selected_by)

        # 1. Gather all constraints for next_pkg_name
        constraints: List[Tuple[str, Range, str]] = []

        # Constraint 1: Root requirement
        root_spec = requirements.get(next_pkg_name)
        if root_spec:
            try:
                root_range = Range(root_spec)
                # Requirer: <root>
                constraints.append(("<root>", root_range, "<root>"))
            except ValueError:
                raise ResolutionError(next_pkg_name, f"Invalid root requirement specification for {next_pkg_name}: {root_spec}")


        # Constraints 2+: Requirements from already selected packages
        for selected_name, selected_version in selected.items():
            if selected_name == next_pkg_name:
                continue # Skip self-references if they somehow appear here

            # Check if selected_name requires next_pkg_name
            try:
                required_deps = index.requirements(selected_name, selected_version)
            except KeyError:
                # Should not happen if index is consistent
                continue 

            if next_pkg_name in required_deps:
                dep_range = required_deps[next_pkg_name]
                # Requirer: name version
                requirer_str = f"{selected_name} {str(selected_version)}"
                constraints.append((requirer_str, dep_range, requirer_str))

        # 2. Identify candidates (Newest first)
        candidates_versions = index.versions(next_pkg_name)

        successful_candidates: List[Version] = []

        for candidate_version in candidates_versions:

            # A. Check if the version satisfies all gathered constraints
            is_constrained_ok = True
            for _, required_range, _ in constraints:
                if not required_range.contains(candidate_version):
                    is_constrained_ok = False
                    break

            if not is_constrained_ok:
                continue

            # B. Check dependency compatibility against already selected packages
            candidate_deps = index.requirements(next_pkg_name, candidate_version)
            is_dependency_ok = True

            # Iterate through candidate's dependencies, sorted alphabetically by dependency name
            for dep_name in sorted(candidate_deps.keys()):
                if dep_name in selected:
                    selected_version = selected[dep_name]
                    required_range = candidate_deps[dep_name]

                    if not required_range.contains(selected_version):
                        is_dependency_ok = False
                        break

            if is_dependency_ok:
                successful_candidates.append(candidate_version)

        # 3. Backtracking Search Loop

        if not successful_candidates:
            # Failure at this node. Construct error message.

            error_lines = [f"cannot resolve {next_pkg_name}"]

            # Constraint explanations (in order they were gathered)
            for requirer, req_range, req_str in constraints:
                error_lines.append(f"  {req_str} requires {next_pkg_name} {str(req_range)}")

            # Version exclusion explanations
            if not candidates_versions:
                error_lines.append(f"  no versions of {next_pkg_name} are known")
            else:
                for candidate_version in candidates_versions:

                    # 1. Check if version is excluded by constraints
                    excluded_by_constraint = False
                    for _, required_range, _ in constraints:
                        if not required_range.contains(candidate_version):
                            error_lines.append(f"  {next_pkg_name} {str(candidate_version)} is excluded by the constraints")
                            excluded_by_constraint = True
                            break

                    if excluded_by_constraint:
                        continue

                    # 2. Check dependency conflicts
                    candidate_deps = index.requirements(next_pkg_name, candidate_version)
                    is_conflict = False

                    # Iterate through dependencies alphabetically
                    for dep_name in sorted(candidate_deps.keys()):
                        if dep_name in selected:
                            selected_version = selected[dep_name]
                            required_range = candidate_deps[dep_name]

                            if not required_range.contains(selected_version):
                                error_lines.append(f"  {next_pkg_name} {str(candidate_version)} requires {dep_name} {str(required_range)}, but {dep_name} {str(selected_version)} is selected")
                                is_conflict = True
                                break

                    if is_conflict:
                        continue


            error_msg = "\n".join(error_lines)
            raise ResolutionError(next_pkg_name, error_msg)

        # Recursive Step: Try each acceptable candidate
        for candidate_version in successful_candidates:

            new_selected = selected.copy()
            new_selected[next_pkg_name] = candidate_version

            # Update history tracking
            new_selected_by = {k: v[:] for k, v in selected_by.items()}
            new_selected_by[next_pkg_name] = [(requirer, selected[requirer]) for requirer, selected in selected_by.items() if next_pkg_name in index.requirements(requirer, selected)]

            # Determine new packages to add to the order
            candidate_deps = index.requirements(next_pkg_name, candidate_version)
            newly_added_names = []
            for dep_name in sorted(candidate_deps.keys()):
                if dep_name not in new_selected:
                    newly_added_names.append(dep_name)

            # The search continues with the current order minus the resolved item, plus new dependencies appended.
            new_order = current_order[1:] + newly_added_names

            # Recurse
            result = search(new_order, new_selected, new_selected_by)
            if result is not None:
                return result # Success path found

        # If all successful candidates failed downstream, this step fails. Raise error.

        # Re-use the logic from the failure block above, as the candidates were acceptable locally but failed globally.
        # Note: When failing after trying all candidates, the explanation must reflect that *all* candidates failed, 
        # which is captured by listing all versions and their reasons for failure (either constraint/conflict or recursion failure).

        # Since the structure required is based on the *first* step that found no acceptable candidate, 
        # and we successfully found acceptable candidates but they led to recursion failure, we must still report failure at this package.

        # Re-running the error construction logic for the final failure state:
        error_lines = [f"cannot resolve {next_pkg_name}"]

        # Constraint explanations
        for requirer, req_range, req_str in constraints:
             error_lines.append(f"  {req_str} requires {next_pkg_name} {str(req_range)}")

        # Version exclusion explanations (These must list all versions that were checked)
        if not candidates_versions:
            error_lines.append(f"  no versions of {next_pkg_name} are known")
        else:
            for candidate_version in candidates_versions:

                # 1. Check if version is excluded by constraints (Checked before recursion)
                excluded_by_constraint = False
                for _, required_range, _ in constraints:
                    if not required_range.contains(candidate_version):
                        error_lines.append(f"  {next_pkg_name} {str(candidate_version)} is excluded by the constraints")
                        excluded_by_constraint = True
                        break

                if excluded_by_constraint:
                    continue

                # 2. Check dependency conflicts (Checked before recursion)
                candidate_deps = index.requirements(next_pkg_name, candidate_version)
                is_conflict = False

                for dep_name in sorted(candidate_deps.keys()):
                    if dep_name in selected:
                        selected_version = selected[dep_name]
                        required_range = candidate_deps[dep_name]

                        if not required_range.contains(selected_version):
                            error_lines.append(f"  {next_pkg_name} {str(candidate_version)} requires {dep_name} {str(required_range)}, but {dep_name} {str(selected_version)} is selected")
                            is_conflict = True
                            break

                # If the version passed constraints and dependency checks, it must have failed downstream. 
                # According to the spec, if it's not excluded by constraint or conflict, we don't list it here. 
                # However, since the recursion failed, we must list it if it was acceptable locally.
                if not excluded_by_constraint and not is_conflict:
                    # This indicates a downstream failure that wasn't a local conflict/constraint violation.
                    # We follow the structure and omit it if it passes local checks, relying on the prompt's focus 
                    # on the *first* step that found *no acceptable candidate*. Since we found some, 
