# resolve/versions.py
import re

class Version:
    """Represents a semantic version MAJOR.MINOR.PATCH."""
    def __init__(self, text: str):
        if not isinstance(text, str):
            raise TypeError("Version must be a string.")

        match = re.fullmatch(r"([0-9]+)\.([0-9]+)\.([0-9]+)", text)
        if not match:
            raise ValueError(f"Invalid version format: {text}. Expected MAJOR.MINOR.PATCH.")

        parts = [int(p) for p in match.groups()]
        self.major = parts[0]
        self.minor = parts[1]
        self.patch = parts[2]

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self < other or self == other

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __gt__(self, other):
        return not (self <= other)

    def __ge__(self, other):
        return self > other or self == other

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def to_tuple(self):
        return (self.major, self.minor, self.patch)

class Range:
    """Represents a set of version constraints."""

    OPERATORS = {
        "==": lambda v: v == Range._parse_version_from_str(v),
        "!=": lambda v: v != Range._parse_version_from_str(v),
        ">=": lambda v: v >= Range._parse_version_from_str(v),
        ">": lambda v: v > Range._parse_version_from_str(v),
        "<=": lambda v: v <= Range._parse_version_from_str(v),
        "<": lambda v: v < Range._parse_version_from_str(v),
    }

    def __init__(self, spec: str):
        self._spec = spec.strip()
        self.constraints = []
        self._parse_spec()

    @staticmethod
    def _parse_version_from_str(v_str: str):
        """Helper to safely parse a version string used in constraints."""
        try:
            return Version(v_str)
        except ValueError:
            raise ValueError(f"Bad version specified in range: {v_str}")

    def _parse_constraint(self, constraint: str):
        constraint = constraint.strip()

        # 1. Wildcard
        if constraint == "*":
            self.constraints.append(lambda v: True)
            return

        # 2. Tilde (~) and Caret (^)
        if constraint.startswith('~'):
            base_spec = constraint[1:].strip()
            if not base_spec:
                raise ValueError(f"Empty spec after '~' in constraint: {constraint}")

            try:
                base_v = self._parse_version_from_str(base_spec)
                major, minor, patch = base_v.to_tuple()

                # ~1.2.3 is >=1.2.3, <1.3.0
                if patch == 0 and minor == 0:
                    # ~0.0.3 is >=0.0.3, <0.0.4
                    upper_bound_parts = (major, minor, patch + 1)
                else:
                    # ~1.2.3 is >=1.2.3, <1.3.0
                    upper_bound_parts = (major, minor + 1, 0)

                lower_bound = base_v
                upper_bound = Version(*upper_bound_parts)

                self.constraints.append(lambda v, l=lower_bound, u=upper_bound: l <= v < u)
                return
            except ValueError as e:
                raise ValueError(f"Invalid tilde constraint format: {constraint}. {e}")


        if constraint.startswith('^'):
            base_spec = constraint[1:].strip()
            if not base_spec:
                raise ValueError(f"Empty spec after '^' in constraint: {constraint}")

            try:
                base_v = self._parse_version_from_str(base_spec)
                major, minor, patch = base_v.to_tuple()

                # ^1.2.3 is >=1.2.3, <2.0.0
                if major == 0 and minor == 0 and patch == 0:
                    # ^0.0.0 is >=0.0.0, <0.0.1
                    upper_bound_parts = (major, minor, patch + 1)
                elif major == 0 and minor == 0:
                    # ^0.0.3 is >=0.0.3, <0.0.4
                    upper_bound_parts = (major, minor, patch + 1)
                else:
                    # ^1.2.3 is >=1.2.3, <2.0.0
                    upper_bound_parts = (major + 1, 0, 0)

                lower_bound = base_v
                upper_bound = Version(*upper_bound_parts)

                self.constraints.append(lambda v, l=lower_bound, u=upper_bound: l <= v < u)
                return
            except ValueError as e:
                raise ValueError(f"Invalid caret constraint format: {constraint}. {e}")


        # 3. Standard operators (==, !=, >=, <=, >, <)
        match = re.match(r"(!=|>=|<=|>|<|==)([0-9]+\.[0-9]+\.[0-9]+)", constraint)
        if match:
            op_str, v_str = match.groups()
            op_func = self.OPERATORS[op_str]
            version = self._parse_version_from_str(v_str)
            self.constraints.append(lambda v, op=op_func, ver=version: op(v))
            return

        raise ValueError(f"Unknown or malformed constraint: {constraint}")

    def _parse_spec(self):
        # Split by comma, ensuring we handle empty segments resulting from split
        constraints_list = [c.strip() for c in self._spec.split(',') if c.strip()]

        if not constraints_list and self._spec.strip() != "":
             raise ValueError("Empty constraint segment detected in spec.")

        for c in constraints_list:
            self._parse_constraint(c)

    def contains(self, version: Version) -> bool:
        """Checks if the version satisfies all constraints."""
        for constraint_func in self.constraints:
            if not constraint_func(version):
                return False
        return True

    def __contains__(self, version: Version):
        return self.contains(version)

    def __str__(self) -> str:
        # Reconstruct spec string without whitespace
        return self._spec.replace(' ', '').replace('\t', '')
